function publicationTargetKeyTupleV1(key: TransientTaskPublicationTargetKeyV1): readonly unknown[] {
	return [
		"omp-transient-task-publication-target-v1",
		"key",
		1,
		key.taskId,
		key.runId,
		key.createId,
		key.publicationTargetId,
	];
}

function equalPublicationTargetKeyV1(
	left: TransientTaskPublicationTargetKeyV1,
	right: TransientTaskPublicationTargetKeyV1,
): boolean {
	return (
		left.schemaVersion === right.schemaVersion &&
		left.taskId === right.taskId &&
		left.runId === right.runId &&
		left.createId === right.createId &&
		left.publicationTargetId === right.publicationTargetId
	);
}

