export interface WorkspaceRetentionPolicy {
	readonly onAgentRelease: "retain" | "delete";
	readonly deletedBytesGraceMs: number;
}

/** Closed settings overlay; omission of the whole key or either field uses defaults. */
export interface WorkspaceRetentionPolicyOverlayV1 {
	readonly onAgentRelease?: "retain" | "delete";
	readonly deletedBytesGraceMs?: number;
}

export const PERSISTENT_WORKSPACE_RETENTION_DEFAULTS_V1 = Object.freeze({
	onAgentRelease: "retain",
	deletedBytesGraceMs: 86_400_000,
} satisfies WorkspaceRetentionPolicy);
export const PERSISTENT_WORKSPACE_DELETED_BYTES_GRACE_MS_MIN_V1 = 0 as const;
export const PERSISTENT_WORKSPACE_DELETED_BYTES_GRACE_MS_MAX_V1 = 2_147_483_647 as const;

export type WorkspaceRetentionPolicyValidationCodeV1 =
	| "workspace_retention_invalid_shape"
	| "workspace_retention_invalid_on_agent_release"
	| "workspace_retention_invalid_deleted_bytes_grace_ms";

export class WorkspaceRetentionPolicyValidationError extends Error {
	constructor(readonly code: WorkspaceRetentionPolicyValidationCodeV1) {
		super(code);
		this.name = "WorkspaceRetentionPolicyValidationError";
	}
}

function decodeWorkspaceRetentionFieldsV1(input: unknown, requireComplete: boolean): WorkspaceRetentionPolicyOverlayV1 {
	const allowedKeys = ["onAgentRelease", "deletedBytesGraceMs"] as const;
	if (input === null || typeof input !== "object" || Array.isArray(input)) {
		throw new WorkspaceRetentionPolicyValidationError("workspace_retention_invalid_shape");
	}
	try {
		const prototype = Object.getPrototypeOf(input);
		if (prototype !== Object.prototype && prototype !== null) {
			throw new WorkspaceRetentionPolicyValidationError("workspace_retention_invalid_shape");
		}
		const keys: string[] = [];
		for (const key of Reflect.ownKeys(input)) {
			if (typeof key !== "string" || !allowedKeys.includes(key as (typeof allowedKeys)[number])) {
				throw new WorkspaceRetentionPolicyValidationError("workspace_retention_invalid_shape");
			}
			keys.push(key);
		}
		if (requireComplete && keys.length !== allowedKeys.length) {
			throw new WorkspaceRetentionPolicyValidationError("workspace_retention_invalid_shape");
		}
		const descriptors = Object.getOwnPropertyDescriptors(input);
		const snapshot: Record<string, unknown> = Object.create(null);
		for (const key of keys) {
			const descriptor = descriptors[key];
			if (!descriptor || !descriptor.enumerable || !("value" in descriptor)) {
				throw new WorkspaceRetentionPolicyValidationError("workspace_retention_invalid_shape");
			}
			snapshot[key] = descriptor.value;
		}
		if (
			Object.hasOwn(snapshot, "onAgentRelease") &&
			snapshot.onAgentRelease !== "retain" &&
			snapshot.onAgentRelease !== "delete"
		) {
			throw new WorkspaceRetentionPolicyValidationError("workspace_retention_invalid_on_agent_release");
		}
		if (
			Object.hasOwn(snapshot, "deletedBytesGraceMs") &&
			(!isStrictContractIntegerV1(snapshot.deletedBytesGraceMs) ||
				snapshot.deletedBytesGraceMs > PERSISTENT_WORKSPACE_DELETED_BYTES_GRACE_MS_MAX_V1)
		) {
			throw new WorkspaceRetentionPolicyValidationError("workspace_retention_invalid_deleted_bytes_grace_ms");
		}
		return Object.freeze(snapshot) as WorkspaceRetentionPolicyOverlayV1;
	} catch (error) {
		if (error instanceof WorkspaceRetentionPolicyValidationError) throw error;
		throw new WorkspaceRetentionPolicyValidationError("workspace_retention_invalid_shape");
	}
}

/** Strict closed decoder for the settings-only retention overlay. */
export function decodeWorkspaceRetentionPolicyOverlayV1(input: unknown): WorkspaceRetentionPolicyOverlayV1 {
	return decodeWorkspaceRetentionFieldsV1(input, false);
}

/** Strict closed decoder for one complete immutable workspace-retention policy. */
export function decodeWorkspaceRetentionPolicyV1(input: unknown): WorkspaceRetentionPolicy {
	return decodeWorkspaceRetentionFieldsV1(input, true) as WorkspaceRetentionPolicy;
}

/** Applies one validated overlay to the frozen defaults and validates the complete result. */
export function materializeWorkspaceRetentionPolicyV1(input: unknown = {}): WorkspaceRetentionPolicy {
	const overlay = decodeWorkspaceRetentionPolicyOverlayV1(input);
	return decodeWorkspaceRetentionPolicyV1({ ...PERSISTENT_WORKSPACE_RETENTION_DEFAULTS_V1, ...overlay });
}

