export const PERSISTENT_MODEL_WORKSPACE_ROOT = "/workspace" as const;
export type PersistentModelWorkspaceRoot = typeof PERSISTENT_MODEL_WORKSPACE_ROOT;

declare const persistentModelWorkspacePathBrand: unique symbol;
declare const canonicalWorkspaceRelativePathBrand: unique symbol;

export type PersistentModelWorkspacePath = string & {
	readonly [persistentModelWorkspacePathBrand]: true;
};

/** Canonical relative POSIX path; the workspace root is represented by "". */
export type CanonicalWorkspaceRelativePath = string & {
	readonly [canonicalWorkspaceRelativePathBrand]: true;
};

export interface PersistentWorkspacePathProjection {
	readonly inputKind: "relative" | "model_absolute";
	readonly modelPath: PersistentModelWorkspacePath;
	readonly relativePath: CanonicalWorkspaceRelativePath;
}

export type PersistentWorkspacePathErrorCode =
	| "workspace_path_empty"
	| "workspace_path_nul"
	| "workspace_path_noncanonical"
	| "workspace_path_escape"
	| "workspace_path_unsupported_absolute"
	| "workspace_path_unsupported_target"
	| "provider_path_contract_violation"
	| "physical_path_projection_failed";

export interface PersistentWorkspacePathFailure {
	readonly code: PersistentWorkspacePathErrorCode;
	readonly modelPath: PersistentModelWorkspacePath | null;
	readonly retryable: false;
}

export interface PersistentWorkspacePathMapper {
	readonly modelRoot: PersistentModelWorkspaceRoot;
	parse(input: string): PersistentWorkspacePathProjection;
	parseReturnedModelPath(input: string): PersistentWorkspacePathProjection;
}

export class PersistentWorkspacePathErrorV1 extends Error {
	constructor(readonly failure: PersistentWorkspacePathFailure) {
		super(failure.code);
		this.name = "PersistentWorkspacePathErrorV1";
	}
}

function rejectPersistentWorkspacePathV1(
	code: PersistentWorkspacePathErrorCode,
	modelPath: PersistentModelWorkspacePath | null = null,
): never {
	throw new PersistentWorkspacePathErrorV1(Object.freeze({ code, modelPath, retryable: false }));
}

function persistentWorkspacePathProjectionV1(input: string): PersistentWorkspacePathProjection {
	if (typeof input !== "string" || input.length === 0) rejectPersistentWorkspacePathV1("workspace_path_empty");
	if (input.includes("\0")) rejectPersistentWorkspacePathV1("workspace_path_nul");
	if (!isWellFormedContractUnicodeV1(input)) rejectPersistentWorkspacePathV1("workspace_path_noncanonical");
	if (
		input.startsWith("~") ||
		input.includes("\\") ||
		input.startsWith("//") ||
		/^[A-Za-z][A-Za-z0-9+.-]*:/.test(input)
	) {
		rejectPersistentWorkspacePathV1("workspace_path_unsupported_target");
	}
	if (input.length > 1 && input.endsWith("/")) rejectPersistentWorkspacePathV1("workspace_path_noncanonical");

	const segments = input.split("/");
	if (segments.includes("..")) rejectPersistentWorkspacePathV1("workspace_path_escape");

	if (input.startsWith("/")) {
		if (input !== PERSISTENT_MODEL_WORKSPACE_ROOT && !input.startsWith(`${PERSISTENT_MODEL_WORKSPACE_ROOT}/`)) {
			rejectPersistentWorkspacePathV1("workspace_path_unsupported_absolute");
		}
		if (posixPath.normalize(input) !== input) rejectPersistentWorkspacePathV1("workspace_path_noncanonical");
		const relativePath =
			input === PERSISTENT_MODEL_WORKSPACE_ROOT ? "" : input.slice(PERSISTENT_MODEL_WORKSPACE_ROOT.length + 1);
		return Object.freeze({
			inputKind: "model_absolute",
			modelPath: input as PersistentModelWorkspacePath,
			relativePath: relativePath as CanonicalWorkspaceRelativePath,
		});
	}

	if (input !== "." && (posixPath.normalize(input) !== input || input.startsWith("./"))) {
		rejectPersistentWorkspacePathV1("workspace_path_noncanonical");
	}
	const relativePath = input === "." ? "" : input;
	const modelPath = (
		relativePath.length === 0 ? PERSISTENT_MODEL_WORKSPACE_ROOT : `${PERSISTENT_MODEL_WORKSPACE_ROOT}/${relativePath}`
	) as PersistentModelWorkspacePath;
	return Object.freeze({
		inputKind: "relative",
		modelPath,
		relativePath: relativePath as CanonicalWorkspaceRelativePath,
	});
}

/** Stable pure parser shared by all six persistent workspace tools. */
export const PERSISTENT_WORKSPACE_PATH_MAPPER_V1: PersistentWorkspacePathMapper = Object.freeze({
	modelRoot: PERSISTENT_MODEL_WORKSPACE_ROOT,
	parse: persistentWorkspacePathProjectionV1,
	parseReturnedModelPath(input: string): PersistentWorkspacePathProjection {
		const projection = persistentWorkspacePathProjectionV1(input);
		if (projection.inputKind !== "model_absolute") {
			rejectPersistentWorkspacePathV1("provider_path_contract_violation", projection.modelPath);
		}
		return projection;
	},
});

/** Provider-private and never serialized or returned in RuntimeBinding. */
export interface RuntimeProviderPathMapper {
	toProviderPath(path: PersistentModelWorkspacePath): string;
	fromProviderPath(path: string): PersistentModelWorkspacePath;
	projectProviderText(text: string): string;
	assertNoPhysicalRoot(text: string): void;
}

