export type WorkspaceControllerLeaseAcquireResult =
	| { readonly status: "acquired"; readonly lease: WorkspaceControllerLease }
	| { readonly status: "busy"; readonly current: WorkspaceControllerLeaseObservation }
	| { readonly status: "ownership_lost" }
	| { readonly status: "deleting"; readonly deleteId: OperationId }
	| { readonly status: "tombstoned"; readonly tombstone: WorkspaceTombstone };

export type WorkspaceControllerLeaseRenewResult =
	| { readonly status: "renewed"; readonly lease: WorkspaceControllerLease }
	| {
			readonly status: "lost";
			readonly current: WorkspaceControllerLeaseObservation | null;
	  };

export type WorkspaceControllerLeaseInspectResult =
	| { readonly status: "absent"; readonly workspaceId: WorkspaceId }
	| { readonly status: "active"; readonly lease: WorkspaceControllerLeaseObservation }
	| { readonly status: "expired"; readonly lease: WorkspaceControllerLeaseObservation }
	| { readonly status: "deleting"; readonly deleteId: OperationId }
	| { readonly status: "tombstoned"; readonly tombstone: WorkspaceTombstone };

export interface WorkspaceControllerLeaseStore {
	/**
	 * Accepts the live ownership capability; the store, not the caller, mints
	 * and durably publishes `leaseId` in the same transaction as acquisition.
	 */
	acquire(request: {
		readonly workspaceId: WorkspaceId;
		readonly ownership: PersistentAgentOwnership;
		readonly ttlMs: number;
	}): Promise<WorkspaceControllerLeaseAcquireResult>;
	renew(request: {
		readonly proof: WorkspaceControllerLeaseProof;
		readonly ownership: PersistentAgentOwnership;
		readonly ttlMs: number;
	}): Promise<WorkspaceControllerLeaseRenewResult>;
	inspect(workspaceId: WorkspaceId): Promise<WorkspaceControllerLeaseInspectResult>;
	revoke(request: {
		readonly workspaceId: WorkspaceId;
		readonly expectedLeaseId: WorkspaceControllerLeaseId | null;
		readonly ownership: PersistentAgentOwnership;
		readonly reasonCode: SafeDiagnosticCodeV1;
	}): Promise<
		{ readonly status: "revoked" | "already_absent"; readonly nextEpoch: number } | { readonly status: "lost" }
	>;
	release(request: {
		readonly proof: WorkspaceControllerLeaseProof;
		readonly ownership: PersistentAgentOwnership;
	}): Promise<{ readonly status: "released" | "already_released" | "lost" }>;
}

export interface WorkspaceDeletionAuthorityProof {
	readonly workspaceId: WorkspaceId;
	readonly deleteId: OperationId;
	readonly deletionAuthorityId: OperationId;
	/** Binds the staged core and complete immutable tuples in §7.4. */
	readonly deletionPlanCoreSha256: Sha256Ref;
	readonly deletionPlanSha256: Sha256Ref;
	readonly agentId: PersistentAgentId;
	readonly controlHostId: string;
	readonly ownerEpoch: number;
	/** Monotonic deletion-authority epoch; never an ownership or controller epoch. */
	readonly epoch: number;
}

export interface WorkspaceDeletionVerificationReceiptV1 {
	readonly schemaVersion: 1;
	readonly workspaceId: WorkspaceId;
	readonly deleteId: OperationId;
	readonly deletionAuthorityId: OperationId;
	readonly deletionPlanCoreSha256: Sha256Ref;
	readonly deletionPlanSha256: Sha256Ref;
	readonly deletionEpoch: number;
	readonly canonicalGeneration: number;
	readonly runtimeAttachmentCreateId: OperationId;
	readonly runtimeAttachmentRevision: number;
	readonly runtimeAttachmentState: "none";
	readonly verifiedAt: ISO8601;
	/** SHA-256 reference of the exact deletion-verification tuple in §7.4. */
	readonly receiptSha256: Sha256Ref;
}

export interface WorkspaceDeletionAuthority {
	readonly proof: WorkspaceDeletionAuthorityProof;
	readonly expectedGeneration: number;
	readonly expectedRuntimeAttachmentCreateId: OperationId;
	readonly expectedRuntimeAttachmentRevision: number;
	/** Controller epoch advanced by this latch; it is not deletion authority. */
	readonly invalidatedControllerEpoch: number;
	readonly verification: WorkspaceDeletionVerificationReceiptV1 | null;
	readonly acquiredAt: ISO8601;
	readonly renewBy: ISO8601;
	readonly expiresAt: ISO8601;
}

export interface WorkspaceDeletionAuthorityObservation {
	readonly workspaceId: WorkspaceId;
	readonly deleteId: OperationId;
	readonly deletionAuthorityId: OperationId;
	readonly deletionPlanCoreSha256: Sha256Ref;
	readonly deletionPlanSha256: Sha256Ref;
	readonly agentId: PersistentAgentId;
	readonly controlHostId: string;
	readonly ownerEpoch: number;
	readonly expectedGeneration: number;
	readonly expectedRuntimeAttachmentCreateId: OperationId;
	readonly expectedRuntimeAttachmentRevision: number;
	readonly verification: "pending" | "verified";
	readonly acquiredAt: ISO8601;
	readonly renewBy: ISO8601;
	readonly expiresAt: ISO8601;
}

export type WorkspaceDeletionAuthorityAcquireResult =
	| {
			readonly status: "acquired";
			readonly authority: WorkspaceDeletionAuthority;
	  }
	| {
			readonly status: "busy";
			readonly current: WorkspaceDeletionAuthorityObservation;
	  }
	| { readonly status: "ownership_lost" }
	| {
			readonly status: "delete_conflict";
			readonly code: "different_delete_id" | "same_id_different_expectation";
			readonly currentDeleteId: OperationId;
	  };

export type WorkspaceDeletionVerificationMismatchCodeV1 =
	| "canonical_generation_mismatch"
	| "attachment_workspace_mismatch"
	| "attachment_create_id_mismatch"
	| "attachment_revision_mismatch"
	| "attachment_not_none";

export type WorkspaceDeletionVerificationResultV1 =
	| {
			readonly status: "verified" | "already_verified";
			readonly receipt: WorkspaceDeletionVerificationReceiptV1;
	  }
	| {
			readonly status: "mismatch";
			readonly code: WorkspaceDeletionVerificationMismatchCodeV1;
	  }
	| {
			readonly status: "conflict";
			readonly current: WorkspaceDeletionVerificationReceiptV1;
	  }
	| { readonly status: "lost" };

export interface WorkspaceDeletionAuthorityStore {
	/**
	 * Latches deletion and invalidates controller publication; it does not read
	 * or claim an atomic transaction with the runtime-attachment filesystem.
	 */
	acquire(request: {
		readonly deletion: WorkspaceDeletionPlanV1;
		readonly deletionPlanCoreSha256: Sha256Ref;
		readonly deletionPlanSha256: Sha256Ref;
		readonly ownership: PersistentAgentOwnership;
		readonly ttlMs: number;
	}): Promise<WorkspaceDeletionAuthorityAcquireResult>;
	renew(request: {
		readonly proof: WorkspaceDeletionAuthorityProof;
		readonly ownership: PersistentAgentOwnership;
		readonly ttlMs: number;
	}): Promise<
		{ readonly status: "renewed"; readonly authority: WorkspaceDeletionAuthority } | { readonly status: "lost" }
	>;
	inspect(
		workspaceId: WorkspaceId,
	): Promise<
		| { readonly status: "absent"; readonly workspaceId: WorkspaceId }
		| { readonly status: "active"; readonly authority: WorkspaceDeletionAuthorityObservation }
		| { readonly status: "expired"; readonly authority: WorkspaceDeletionAuthorityObservation }
		| { readonly status: "tombstoned"; readonly tombstone: WorkspaceTombstone }
	>;
	/** Persists the exact post-latch reread before any destructive effect. */
	verify(request: {
		readonly proof: WorkspaceDeletionAuthorityProof;
		readonly ownership: PersistentAgentOwnership;
		readonly observedCanonicalGeneration: number;
		readonly attachment: RuntimeAttachmentRecordV1;
	}): Promise<WorkspaceDeletionVerificationResultV1>;
	release(request: {
		readonly proof: WorkspaceDeletionAuthorityProof;
		readonly ownership: PersistentAgentOwnership;
	}): Promise<{ readonly status: "released" | "already_released" | "lost" }>;
}

