export type ConfidentialTransientTaskIsolationOwnerLivenessEvidenceV1 = {
	readonly schemaVersion: 1;
	readonly taskId: string;
	readonly runId: string;
	readonly createId: OperationId;
	readonly effectOperationId: OperationId;
	readonly creatorDescriptorSha256: Sha256Ref;
	readonly requestSha256: Sha256Ref;
	readonly attemptSha256: Sha256Ref;
	readonly observedClaim: ConfidentialTransientTaskIsolationOwnershipClaimV1;
	readonly probingControlHostId: string;
	readonly evidenceSha256: Sha256Ref;
} & (
	| {
			readonly verdict: "stale";
			readonly basis: "same_host_pid_absent" | "same_host_process_start_token_mismatch";
	  }
	| {
			readonly verdict: "live";
			readonly basis: "same_host_process_identity_live";
	  }
	| {
			readonly verdict: "indeterminate";
			readonly basis:
				| "different_control_host"
				| "missing_process_start_token"
				| "process_probe_unsupported"
				| "process_probe_permission_denied"
				| "process_probe_unavailable";
	  }
);

