/**
 * Confidential store in the same transaction domain as workspace authority.
 * The initial exclusive-create attempt is supplied to workspace-authority create;
 * prepareEffect may install only a stale-same-owner CAS or pre-bind release.
 */
export interface ConfidentialTransientTaskIsolationCreatorStoreV1 {
	/** Stable host identity for the injected raw process probe and every emitted liveness record. */
	readonly controlHostId: string;
	readonly processIdentityProbe: ConfidentialTransientTaskIsolationOwnerProcessIdentityProbeV1;
	prepareEffect(request: {
		readonly expectedWorkspaceRevision: number;
		readonly effectRequest: Extract<
			ConfidentialTransientTaskIsolationOwnershipClaimEffectRequestV1,
			{ operation: "stale_same_owner_cas_adopt" | "pre_bind_cas_release" }
		>;
		readonly controller: TransientTaskControllerAuthorityProofV1;
	}): Promise<
		| {
				readonly status: "prepared" | "already_prepared";
				readonly preparation: ConfidentialTransientTaskIsolationPreparingAuthorityV1;
		  }
		| { readonly status: "revision_conflict" | "controller_lost" | "conflict" | "invalid" }
	>;
	transitionEffectToOutcomeUnknown(request: {
		readonly expectedWorkspaceRevision: number;
		readonly expectedAttemptSha256: Sha256Ref;
		readonly controller: TransientTaskControllerAuthorityProofV1;
	}): Promise<
		| {
				readonly status: "transitioned" | "already_outcome_unknown";
				readonly attempt: ConfidentialTransientTaskIsolationOwnershipClaimEffectAttemptV1;
		  }
		| { readonly status: "revision_conflict" | "controller_lost" | "conflict" | "invalid" }
	>;
	inspectEffect(
		request: TransientTaskIsolationOwnershipClaimEffectInspectRequestV1,
	): Promise<TransientTaskIsolationOwnershipClaimEffectInspectResultV1>;
	adoptEffect(
		request: ConfidentialTransientTaskIsolationOwnershipClaimEffectAdoptRequestV1,
	): Promise<ConfidentialTransientTaskIsolationOwnershipClaimEffectAdoptResultV1>;
	recordReadyToBind(request: {
		readonly expectedWorkspaceRevision: number;
		readonly ensureRequestSha256: Sha256Ref;
		readonly cleanupDescriptor: ConfidentialTransientTaskIsolationCleanupDescriptorV1;
		readonly controller: TransientTaskControllerAuthorityProofV1;
		readonly preparedAt: ISO8601;
	}): Promise<
		| {
				readonly status: "recorded" | "already_recorded";
				readonly receipt: ConfidentialTransientTaskIsolationReadyToBindReceiptV1;
		  }
		| { readonly status: "revision_conflict" | "controller_lost" | "claim_not_current" | "conflict" | "invalid" }
	>;
	recordBound(request: {
		readonly expectedWorkspaceRevision: number;
		readonly readyReceiptSha256: Sha256Ref;
		readonly bindReceipt: TransientTaskPublicationTargetBindReceiptV1;
		readonly controller: TransientTaskControllerAuthorityProofV1;
	}): Promise<
		| {
				readonly status: "recorded" | "already_recorded";
				readonly preparation: Extract<ConfidentialTransientTaskIsolationPreparingAuthorityV1, { state: "bound" }>;
		  }
		| { readonly status: "revision_conflict" | "controller_lost" | "conflict" | "invalid" }
	>;
}

