/** Total strict validator for the complete path-free durable binding projection. */
export function validateTransientTaskPublicationTargetBindingV1(
	input: unknown,
): input is TransientTaskPublicationTargetBindingV1 {
	try {
		const fields = [
			"schemaVersion",
			"key",
			"isolationCleanupId",
			"bindingRevision",
			"renewalSequence",
			"progress",
			"updatedAt",
		] as const;
		if (
			!isStrictContractRecordV1(input, fields) ||
			input.schemaVersion !== 1 ||
			!isStrictContractIdentityV1(input.isolationCleanupId) ||
			!isStrictContractIso8601V1(input.updatedAt)
		)
			return false;
		const key = requirePublicationTargetKeyV1(input.key);
		const isolationCleanupId = input.isolationCleanupId;
		if (input.progress === null || typeof input.progress !== "object" || Array.isArray(input.progress)) return false;
		const progress = input.progress as Record<string, unknown>;
		const state = progress.state;
		if (state === "bind_outcome_unknown" || state === "bind_not_applied") {
			if (
				input.bindingRevision !== 0 ||
				input.renewalSequence !== 0 ||
				!isStrictContractRecordV1(progress, [
					"state",
					"attempt",
					"cleanupDescriptorSha256",
					"isolationCreatorPreparationReceiptSha256",
					"isolationOwnershipClaimReceiptSha256",
				]) ||
				typeof progress.cleanupDescriptorSha256 !== "string" ||
				!SHA256_REF_V1.test(progress.cleanupDescriptorSha256) ||
				typeof progress.isolationCreatorPreparationReceiptSha256 !== "string" ||
				!SHA256_REF_V1.test(progress.isolationCreatorPreparationReceiptSha256) ||
				typeof progress.isolationOwnershipClaimReceiptSha256 !== "string" ||
				!SHA256_REF_V1.test(progress.isolationOwnershipClaimReceiptSha256)
			)
				return false;
			requirePublicationTargetAttemptInspectionV1(progress.attempt);
			return true;
		}
		if (!isStrictContractIntegerV1(input.bindingRevision, 1) || !isStrictContractIntegerV1(input.renewalSequence))
			return false;
		if (state === "live") {
			if (
				!isStrictContractRecordV1(progress, [
					"state",
					"bindReceipt",
					"lastRenewalReceipt",
					"currentReceiptSha256",
					"renewBy",
					"expiresAt",
					"publicationClaim",
					"cleanupClaim",
					"transition",
				])
			)
				return false;
			const bind = requirePublicationTargetBindReceiptV1(progress.bindReceipt, key, isolationCleanupId);
			const renewal =
				progress.lastRenewalReceipt === null
					? null
					: requirePublicationTargetRenewalReceiptV1(progress.lastRenewalReceipt, key, isolationCleanupId);
			const current = renewal ?? bind;
			if (
				renewal !== null &&
				(renewal.bindingOperationId !== bind.bindingOperationId ||
					renewal.renewedAt < bind.boundAt ||
					(renewal.renewalSequence === 1 && renewal.previousReceiptSha256 !== bind.receiptSha256))
			)
				return false;
			const currentTimestamp = renewal?.renewedAt ?? bind.boundAt;
			if (
				input.bindingRevision !== current.bindingRevision ||
				input.renewalSequence !== current.renewalSequence ||
				progress.currentReceiptSha256 !== current.receiptSha256 ||
				progress.renewBy !== current.renewBy ||
				progress.expiresAt !== current.expiresAt ||
				!isStrictContractIso8601V1(progress.renewBy) ||
				!isStrictContractIso8601V1(progress.expiresAt) ||
				input.updatedAt < currentTimestamp
			)
				return false;
			const publicationClaim =
				progress.publicationClaim === null
					? null
					: requirePublicationTargetPublicationClaimV1(progress.publicationClaim, key, isolationCleanupId);
			const cleanupClaim =
				progress.cleanupClaim === null
					? null
					: requirePublicationTargetCleanupClaimV1(progress.cleanupClaim, key, isolationCleanupId);
			if (publicationClaim !== null && cleanupClaim !== null) return false;
			if (
				publicationClaim !== null &&
				(publicationClaim.bindingRevision !== input.bindingRevision ||
					publicationClaim.renewalSequence !== input.renewalSequence ||
					publicationClaim.bindingReceiptSha256 !== current.receiptSha256 ||
					publicationClaim.bindingAuthoritySha256 !== current.authoritySha256 ||
					publicationClaim.isolationNamespaceSha256 !== bind.isolationNamespaceSha256 ||
					publicationClaim.isolationOwnerManifestSha256 !== bind.isolationOwnerManifestSha256 ||
					publicationClaim.isolationCreatorDescriptorSha256 !== bind.isolationCreatorDescriptorSha256 ||
					publicationClaim.claimedAt > input.updatedAt)
			)
				return false;
			if (
				cleanupClaim !== null &&
				(cleanupClaim.access !== "live" ||
					cleanupClaim.bindingRevision !== input.bindingRevision ||
					cleanupClaim.renewalSequence !== input.renewalSequence ||
					cleanupClaim.bindingReceiptSha256 !== current.receiptSha256 ||
					cleanupClaim.bindingAuthoritySha256 !== current.authoritySha256 ||
					cleanupClaim.cleanupDescriptorSha256 !== bind.cleanupDescriptorSha256 ||
					cleanupClaim.isolationNamespaceSha256 !== bind.isolationNamespaceSha256 ||
					cleanupClaim.isolationOwnerManifestSha256 !== bind.isolationOwnerManifestSha256 ||
					cleanupClaim.isolationCreatorDescriptorSha256 !== bind.isolationCreatorDescriptorSha256 ||
					cleanupClaim.claimedAt > input.updatedAt)
			)
				return false;
			requirePublicationTargetTransitionV1(progress.transition, ["renewal", "release", "expiry"]);
			const transition = progress.transition;
			if (transition !== null) {
				if (
					typeof transition !== "object" ||
					Array.isArray(transition) ||
					!("state" in transition) ||
					typeof transition.state !== "string"
				)
					return false;
				const transitionState = transition.state;
				if (transitionState.startsWith("renewal_") && (publicationClaim !== null || cleanupClaim !== null))
					return false;
				if (transitionState.startsWith("expiry_") && (publicationClaim !== null || cleanupClaim !== null))
					return false;
				if (transitionState.startsWith("release_") && cleanupClaim === null) return false;
			}
			return true;
		}
		if (state === "cleanup_due") {
			if (
				!isStrictContractRecordV1(progress, [
					"state",
					"cleanupDueReceipt",
					"currentReceiptSha256",
					"expiresAt",
					"cleanupClaim",
					"transition",
				])
			)
				return false;
			const cleanupDue = requirePublicationTargetCleanupDueReceiptV1(
				progress.cleanupDueReceipt,
				key,
				isolationCleanupId,
			);
			if (
				input.bindingRevision !== cleanupDue.bindingRevision ||
				input.renewalSequence !== cleanupDue.renewalSequence ||
				progress.currentReceiptSha256 !== cleanupDue.receiptSha256 ||
				progress.expiresAt !== cleanupDue.expiresAt ||
				input.updatedAt < cleanupDue.cleanupDueAt
			)
				return false;
			const cleanupClaim =
				progress.cleanupClaim === null
					? null
					: requirePublicationTargetCleanupClaimV1(progress.cleanupClaim, key, isolationCleanupId);
			if (
				cleanupClaim !== null &&
				(cleanupClaim.access !== "cleanup_due" ||
					cleanupClaim.bindingRevision !== input.bindingRevision ||
					cleanupClaim.renewalSequence !== input.renewalSequence ||
					cleanupClaim.bindingReceiptSha256 !== cleanupDue.receiptSha256 ||
					cleanupClaim.bindingAuthoritySha256 !== cleanupDue.authoritySha256 ||
					cleanupClaim.claimedAt > input.updatedAt)
			)
				return false;
			requirePublicationTargetTransitionV1(progress.transition, ["release"]);
			if (progress.transition !== null && cleanupClaim === null) return false;
			return true;
		}
		if (state === "terminal") {
			if (
				!isStrictContractRecordV1(progress, ["state", "terminalState", "releaseReceipt"]) ||
				(progress.terminalState !== "released" && progress.terminalState !== "expired")
			)
				return false;
			const release = requirePublicationTargetReleaseReceiptV1(progress.releaseReceipt, key, isolationCleanupId);
			return (
				progress.terminalState === release.state &&
				input.bindingRevision === release.bindingRevision &&
				input.renewalSequence === release.renewalSequence &&
				input.updatedAt >= release.terminalAt
			);
		}
		return false;
	} catch {
		return false;
	}
}

/** Strict decoder; malformed, open, stale, or digest-inconsistent rows fail closed. */
export function decodeTransientTaskPublicationTargetBindingV1(input: unknown): TransientTaskPublicationTargetBindingV1 {
	if (!validateTransientTaskPublicationTargetBindingV1(input)) {
		throw new TransientTaskPublicationTargetBindingValidationErrorV1("invalid_shape");
	}
	return input;
}
