/**
 * Closed parent-delivery derivation table. Every member uses a key selector;
 * `selector.keyUtf8` must be the exact canonical UTF-8 JSON tuple specified in
 * the sole normative table below in §5.2 for the same `domain` and `selectorBinding`.
 */
export type TransientTaskParentDeliveryEffectIdentityDerivationV1 = {
	readonly namespace: "parent_delivery";
	readonly namespaceId: OperationId;
	readonly selector: { readonly kind: "key"; readonly keyUtf8: string };
} & (
	| {
			readonly domain: "foreground_settlement";
			readonly selectorBinding: {
				readonly resultPublicationTargetId: TransientTaskResultPublicationTargetId;
				readonly parentSessionId: string;
				readonly toolCallId: string;
				readonly foregroundMemberIndex: number;
			};
	  }
	| {
			readonly domain: "foreground_session_append";
			readonly selectorBinding: {
				readonly parentSessionId: string;
				readonly toolCallId: string;
				readonly foregroundMemberIndex: number;
			};
	  }
	| {
			readonly domain: "detached_enqueue";
			readonly selectorBinding: {
				readonly resultPublicationTargetId: TransientTaskResultPublicationTargetId;
				readonly ownerId: string;
				readonly jobId: string;
				readonly deliveryEpoch: number;
			};
	  }
	| {
			readonly domain: "detached_settled_result";
			readonly selectorBinding: { readonly identitySha256: Sha256Ref };
	  }
	| {
			readonly domain: "detached_reservation";
			readonly selectorBinding:
				| {
						readonly identitySha256: Sha256Ref;
						readonly disposition: "hub_wait_consumption";
						readonly hubWaitInvocationId: OperationId;
				  }
				| {
						readonly identitySha256: Sha256Ref;
						readonly disposition:
							| "hub_jobs_consumption"
							| "hub_cancel_consumption"
							| "current_epoch_enqueue"
							| "delivery_epoch_invalidation"
							| "missing_owner_dead_letter";
						readonly hubWaitInvocationId: null;
				  };
	  }
	| {
			readonly domain: "detached_suppression";
			readonly selectorBinding:
				| {
						readonly identitySha256: Sha256Ref;
						readonly consumer: "hub_wait";
						readonly hubWaitInvocationId: OperationId;
				  }
				| {
						readonly identitySha256: Sha256Ref;
						readonly consumer: "hub_jobs" | "hub_cancel";
						readonly hubWaitInvocationId: null;
				  };
	  }
	| {
			readonly domain: "detached_sink_enqueue";
			readonly selectorBinding: { readonly identitySha256: Sha256Ref };
	  }
	| {
			readonly domain: "detached_session_outbox";
			readonly selectorBinding: {
				readonly identitySha256: Sha256Ref;
				readonly sinkOperationId: OperationId;
			};
	  }
	| {
			readonly domain: "detached_primary_session_persistence";
			readonly selectorBinding: {
				readonly primarySessionId: string;
				readonly primarySessionGenerationSha256: Sha256Ref;
				readonly primaryBranchGenerationSha256: Sha256Ref;
				readonly primaryBranchAnchorEntryId: string | null;
				readonly appendParentEntryId: string | null;
				readonly primarySessionEntryId: string;
				readonly orderedOutboxMemberSha256s: readonly [Sha256Ref, ...Sha256Ref[]];
			};
	  }
	| {
			readonly domain: "detached_consumption";
			readonly selectorBinding: {
				readonly identitySha256: Sha256Ref;
				readonly reservationId: OperationId;
				readonly disposition: "hub_jobs_consumption" | "hub_wait_consumption" | "hub_cancel_consumption";
			};
	  }
	| {
			readonly domain: "detached_terminal_commit";
			readonly selectorBinding: {
				readonly identitySha256: Sha256Ref;
				readonly reservationId: OperationId;
				readonly disposition: "current_epoch_enqueue";
			};
	  }
	| {
			readonly domain: "detached_epoch_invalidation";
			readonly selectorBinding: {
				readonly identitySha256: Sha256Ref;
				readonly reservationId: OperationId;
				readonly disposition: "delivery_epoch_invalidation";
			};
	  }
	| {
			readonly domain: "detached_missing_owner_dead_letter";
			readonly selectorBinding: {
				readonly identitySha256: Sha256Ref;
				readonly reservationId: OperationId;
				readonly disposition: "missing_owner_dead_letter";
			};
	  }
	| {
			readonly domain: "detached_reservation_release";
			readonly selectorBinding: {
				readonly identitySha256: Sha256Ref;
				readonly reservationId: OperationId;
				readonly reason:
					| "hub_message_won"
					| "hub_wait_timeout"
					| "hub_wait_aborted"
					| "reservation_not_selected"
					| "sink_proven_not_applied";
			};
	  }
);

