export type TransientTaskEffectIdentityDerivationV1 =
	| {
			readonly namespace: "capture_member";
			readonly namespaceId: OperationId;
			readonly domain: TransientTaskCaptureMemberIdentityDomainV1;
			readonly selector: TransientTaskEffectIdentitySelectorV1;
	  }
	| {
			readonly namespace: "capture_materialization";
			readonly namespaceId: OperationId;
			readonly domain: TransientTaskCaptureMaterializationIdentityDomainV1;
			readonly selector: TransientTaskEffectIdentitySelectorV1;
	  }
	| {
			readonly namespace: "message_generation";
			readonly namespaceId: OperationId;
			readonly domain: TransientTaskMessageGenerationIdentityDomainV1;
			readonly selector: TransientTaskEffectIdentitySelectorV1;
	  }
	| {
			readonly namespace: "capture_subeffect";
			readonly namespaceId: OperationId;
			readonly domain: TransientTaskCaptureSubeffectIdentityDomainV1;
			readonly selector: TransientTaskEffectIdentitySelectorV1;
	  }
	| {
			readonly namespace: "semantic_merge_step";
			readonly namespaceId: OperationId;
			readonly domain: TransientTaskSemanticMergeStepIdentityDomainV1;
			readonly selector: TransientTaskEffectIdentitySelectorV1;
	  }
	| {
			readonly namespace: "semantic_merge_subeffect";
			readonly namespaceId: OperationId;
			readonly domain: TransientTaskSemanticMergeSubeffectIdentityDomainV1;
			readonly selector: TransientTaskEffectIdentitySelectorV1;
	  }
	| {
			readonly namespace: "binding_operation";
			readonly namespaceId: OperationId;
			readonly domain: TransientTaskBindingOperationIdentityDomainV1;
			readonly selector: TransientTaskEffectIdentitySelectorV1;
	  }
	| {
			readonly namespace: "payload_retention";
			readonly namespaceId: OperationId;
			readonly domain: TransientTaskPayloadRetentionIdentityDomainV1;
			readonly selector: TransientTaskEffectIdentitySelectorV1;
	  }
	| TransientTaskParentDeliveryEffectIdentityDerivationV1;

/** Pure canonical derivation; implementations return `ttei1_` plus lowercase SHA-256 hex. */
export function deriveTransientTaskEffectOperationIdV1(
	derivation: TransientTaskEffectIdentityDerivationV1,
): OperationId {
	const selector: readonly CanonicalRuntimeValue[] =
		derivation.selector.kind === "ordinal"
			? ["ordinal", derivation.selector.ordinal]
			: ["key", derivation.selector.keyUtf8];
	const tuple: readonly CanonicalRuntimeValue[] = [
		"omp-transient-task-effect-identity-v1",
		"derive",
		1,
		derivation.namespaceId,
		derivation.domain,
		selector,
	];
	return `ttei1_${createHash("sha256").update(encodeCanonicalRuntimeTupleV1(tuple)).digest("hex")}` as OperationId;
}

