/** Closed error envelope for terminal task branches that produced no SingleResult. */
export type TransientTaskResultlessTerminalErrorEnvelopeV1 =
	| {
			readonly code: "pre_result_failure";
			readonly source: "structured_subagent";
			readonly structuredSubagentKind: "preflight" | "isolation" | "execution";
			/** Exact StructuredSubagentError.message, before the outer source template. */
			readonly sourceMessage: string;
	  }
	| {
			readonly code: "pre_result_failure";
			readonly source: "task_tool_caught_value";
			readonly structuredSubagentKind: null;
			/** Exact Error.message or String(value), before the task-tool failure template. */
			readonly sourceMessage: string;
	  }
	| {
			readonly code: "pre_result_failure";
			readonly source: "detached_outer_caught_value";
			readonly structuredSubagentKind: null;
			/** Exact Error.message or String(value); the detached outer catch adds no prefix. */
			readonly sourceMessage: string;
	  }
	| {
			readonly code: "detached_pre_execution_abort";
			readonly source: "async_job_abort";
			readonly structuredSubagentKind: null;
			readonly sourceMessage: "Aborted before execution";
	  }
	| {
			readonly code: "controller_interrupted_before_cleanup";
			readonly source: "runtime_controller";
			readonly structuredSubagentKind: null;
			readonly sourceMessage: null;
	  }
	| {
			readonly code: "runtime_interrupted_before_result";
			readonly source: "runtime";
			readonly structuredSubagentKind: null;
			/** Exact durable runtime terminal error text, before the outer source template. */
			readonly sourceMessage: string;
	  }
	| {
			readonly code: "single_result_invalid";
			readonly source: "single_result_projection";
			readonly structuredSubagentKind: null;
			readonly sourceMessage: null;
	  }
	| {
			readonly code: "single_result_payload_too_large";
			readonly source: "single_result_projection";
			readonly structuredSubagentKind: null;
			readonly sourceMessage: null;
			readonly observedUtf8ByteLength: number;
			readonly maximumUtf8ByteLength: number;
	  }
	| {
			/** Sole bounded last-resort member; it contains no producer-controlled text. */
			readonly code: "resultless_source_unrepresentable";
			readonly source: "resultless_projection";
			readonly structuredSubagentKind: null;
			readonly sourceMessage: null;
	  };

