				readonly status: "failed";
				readonly resultText: null;
				readonly errorText: string;
				readonly transientTaskCompletion: TransientTaskAsyncJobCompletionHandoffV1;
				readonly transientTaskSettlementBlock: null;
				readonly notAppliedReceiptSha256: Sha256Ref;
				readonly blockSha256: null;
