/** Existing manager plus one semantically distinct transient-task registration path. */
export interface AsyncJobManagerSettlementBridgeV1 extends AsyncJobManagerTransientTaskSettlementStoreResolverV1 {
	/** Canonical plain-job API remains string-returning and has no settlement contract. */

	register(
		type: "bash" | "task",
		label: string,
		run: (ctx: {
			jobId: string;
			signal: AbortSignal;
			reportProgress: (text: string, details?: Record<string, unknown>) => Promise<void>;
			markRunning: () => void;
		}) => Promise<string>,
		options?: AsyncJobRegisterOptions,
	): string;
	registerTransientTask(
		label: string,
		run: (context: {
			readonly jobId: string;
			readonly signal: AbortSignal;
			readonly reportProgress: (text: string, details?: Readonly<Record<string, unknown>>) => Promise<void>;
			readonly markRunning: () => void;
			/**
			 * Must resolve durably before TransientTaskDetachedSettlementStoreV1.prepare.
			 * Only prepared/already-prepared returns to task code; any other store result
			 * stops this run before settlement effects and remains point-recovery-only.
			 */
			readonly freezeSettlementRecovery: (
				input: ConfidentialAsyncJobTransientTaskFreezeSettlementRecoveryInputV1,
			) => Promise<
				Extract<
					ConfidentialAsyncJobTransientTaskRecoveryPrepareResultV1,
					{ readonly status: "prepared" | "already_prepared" }
				>
			>;
		}) => Promise<ConfidentialTransientTaskAsyncJobRunResultV1>,
		options: {
			readonly id?: string;
			readonly agentId: string;
			readonly queued?: boolean;
			readonly ownerId: string;
			readonly ownerSessionId: string;
			readonly ownerSessionGenerationSha256: Sha256Ref;
			readonly deliveryEpoch: number;
			readonly onProgress?: (text: string) => void | Promise<void>;
		},
	): string;
	/**
	 * Owner/session-scoped point recovery of the exact durable row. Recovery is
	 * performed from its frozen attempt and never requires a retained callback.
	 */
	resumeTransientTaskSettlement(request: {
		readonly ownerSessionIndex: ConfidentialAsyncJobTransientTaskRecoveryOwnerSessionIndexV1;
		readonly jobId: string;
		readonly expectedRecoveryRecordSha256: Sha256Ref;
		/** Reused unchanged for this point inspect/adopt sequence. */
		readonly requestedAt: ISO8601;
	}): Promise<ConfidentialAsyncJobTransientTaskSettlementResumeResultV1>;
	/**
	 * Enumerate, inspect, adopt, and rehydrate every unresolved row before
	 * arbiter visibility; return exactly one result per entry in enumeration order.
	 */
	rehydrateTransientTaskSettlements(request: {
		readonly ownerSessionIndex: ConfidentialAsyncJobTransientTaskRecoveryOwnerSessionIndexV1;
		readonly requestedAt: ISO8601;
	}): Promise<readonly ConfidentialAsyncJobTransientTaskSettlementResumeResultV1[]>;
	/** Owner-scoped and side-effect-free: no acknowledgement, suppression, or enqueue. */
	inspectSettledRow(
		request: ConfidentialAsyncJobSettledRowInspectRequestV1,
	): Promise<ConfidentialAsyncJobSettledRowInspectResultV1>;
}

