/** Sole canonical constructor for the preselection startup barrier request. */
export function buildTransientTaskHubWaitMessagePreselectionStartupResumeRequestV1(
	core: Omit<ConfidentialTransientTaskHubWaitMessagePreselectionStartupResumeRequestV1, "requestSha256">,
): ConfidentialTransientTaskHubWaitMessagePreselectionStartupResumeRequestV1 {
	const requestSha256 = sha256CanonicalRuntimeTupleHexV1([
		"omp-hub-wait-message-preselection-v1",
		"startup-resume-request",
		1,
		core.currentAuthority.authoritySha256,
		core.enumeration.requestSha256,
		core.requestedAt,
	]);
	return { ...core, requestSha256 };
}

