export type TransientTaskHubWaitPeerLivenessReasonV1 = "filtered_sender_not_running" | "no_running_peers";

export type TransientTaskHubWaitPeerLivenessErrorTextV1 =
	| "IRC wait aborted: no running peers remain"
	| `IRC wait aborted: agent "${string}" is not running`;

export type ConfidentialTransientTaskHubWaitPeerLivenessExitV1 =
	| {
			readonly reason: "filtered_sender_not_running";
			readonly fromFilter: string;
			readonly errorTextUtf8: TransientTaskHubWaitPeerLivenessErrorTextV1;
			readonly errorTextUtf8Sha256: Sha256Ref;
			readonly errorTextUtf8ByteLength: number;
	  }
	| {
			readonly reason: "no_running_peers";
			readonly fromFilter: null;
			readonly errorTextUtf8: "IRC wait aborted: no running peers remain";
			readonly errorTextUtf8Sha256: Sha256Ref;
			readonly errorTextUtf8ByteLength: number;
	  };

/** Total literal renderer; the filtered interpolation is the exact bound filter bytes. */
export function renderTransientTaskHubWaitPeerLivenessErrorTextV1(
	reason: TransientTaskHubWaitPeerLivenessReasonV1,
	fromFilter: string | null,
): TransientTaskHubWaitPeerLivenessErrorTextV1 {
	if (reason === "filtered_sender_not_running" && isStrictContractIdentityV1(fromFilter)) {
		return `IRC wait aborted: agent "${fromFilter}" is not running`;
	}
	if (reason === "no_running_peers" && fromFilter === null) return "IRC wait aborted: no running peers remain";
	throw new TypeError("Invalid Hub wait peer-liveness reason/filter pair");
}

/** Strictly validates the reason/filter/literal/hash/length relation. */
export function validateTransientTaskHubWaitPeerLivenessExitV1(
	exit: unknown,
): exit is ConfidentialTransientTaskHubWaitPeerLivenessExitV1 {
	return projectHubPeerLivenessExitTupleV1(exit) !== null;
}

/** Exact terminal no-selection observation; `no_candidate` is not terminal and cannot retire a target. */
export type ConfidentialTransientTaskHubWaitMessageNoSelectionExitV1 =
	| {
			readonly status: "not_selected";
			readonly reason: "invocation_already_closed" | "reservation_selection_lost";
			readonly messageSha256: Sha256Ref;
			readonly selectorInstallRequestSha256: Sha256Hex;
			readonly captureRequestSha256: Sha256Hex;
			readonly exitSha256: Sha256Ref;
	  }
	| {
			readonly status: "timeout_before_selection" | "cancelled_before_selection";
			readonly selectorInstallRequestSha256: Sha256Hex;
			readonly sendAwaitOutboundReceiptSha256: Sha256Ref | null;
			readonly exitSha256: Sha256Ref;
	  }
	| {
			readonly status: "peer_liveness_ended_before_selection";
			readonly peerLivenessExit: ConfidentialTransientTaskHubWaitPeerLivenessExitV1;
			readonly selectorInstallRequestSha256: Sha256Hex;
			readonly exitSha256: Sha256Ref;
	  }
	| {
			readonly status: "job_won_before_message_selection";
			readonly winnerJobId: string;
			readonly selectorInstallRequestSha256: Sha256Hex;
			readonly exitSha256: Sha256Ref;
	  }
	| {
			readonly status: "send_delivery_failed_before_selection";
			readonly sendAwaitOutboundReceiptSha256: Sha256Ref;
			readonly selectorInstallRequestSha256: Sha256Hex;
			readonly exitSha256: Sha256Ref;
	  };

