function hubCanonicalValuesEqualV1(left: unknown, right: unknown): boolean {
	if (Array.isArray(left) || Array.isArray(right)) {
		if (!Array.isArray(left) || !Array.isArray(right) || left.length !== right.length) return false;
		for (let index = 0; index < left.length; index++) {
			if (!hubCanonicalValuesEqualV1(left[index], right[index])) return false;
		}
		return true;
	}
	if (left === null || right === null || typeof left !== "object" || typeof right !== "object") {
		return Object.is(left, right);
	}
	const leftKeys = Reflect.ownKeys(left);
	const rightKeys = Reflect.ownKeys(right);
	if (leftKeys.length !== rightKeys.length || leftKeys.some((key, index) => key !== rightKeys[index])) return false;
	for (const key of leftKeys) {
		const leftDescriptor = Object.getOwnPropertyDescriptor(left, key);
		const rightDescriptor = Object.getOwnPropertyDescriptor(right, key);
		if (
			leftDescriptor === undefined ||
			rightDescriptor === undefined ||
			!("value" in leftDescriptor) ||
			!("value" in rightDescriptor) ||
			!hubCanonicalValuesEqualV1(leftDescriptor.value, rightDescriptor.value)
		)
			return false;
	}
	return true;
}

