function projectHubWinnerRecoveryRefTupleV1(input: unknown): readonly unknown[] | null {
	if (
		!isStrictContractRecordV1(input, [
			"key",
			"returnTargetSha256",
			"returnTargetRegistrationReceiptSha256",
			"preselectionClaimSha256",
			"messageSha256",
			"captureRequestSha256",
			"selectorInstallRequestSha256",
			"selectionReceiptSha256",
			"state",
			"stateSha256",
		])
	)
		return null;
	const key = projectHubWinnerKeyTupleV1(input.key);
	if (
		key === null ||
		!isHubSha256RefV1(input.returnTargetSha256) ||
		input.returnTargetSha256 !== key[8] ||
		!isHubSha256RefV1(input.returnTargetRegistrationReceiptSha256) ||
		!isHubSha256RefV1(input.preselectionClaimSha256) ||
		!isHubSha256RefV1(input.messageSha256) ||
		!isHubSha256HexV1(input.captureRequestSha256) ||
		!isHubSha256HexV1(input.selectorInstallRequestSha256) ||
		!isHubSha256RefV1(input.selectionReceiptSha256) ||
		(input.state !== "active" && input.state !== "completed") ||
		!isHubSha256RefV1(input.stateSha256)
	)
		return null;
	return [
		"omp-hub-wait-message-winner-v1",
		"recovery-ref",
		1,
		key,
		input.returnTargetSha256,
		input.returnTargetRegistrationReceiptSha256,
		input.preselectionClaimSha256,
		input.messageSha256,
		input.selectorInstallRequestSha256,
		input.captureRequestSha256,
		input.selectionReceiptSha256,
		input.state,
		input.stateSha256,
	];
}

function projectHubWinnerRecoveryEnumerationTupleV1(input: unknown, withDigest = true): readonly unknown[] | null {
	const value = hubCanonicalRecordV1(input, ["status", "continuations", "requestSha256"], "resultSha256", withDigest);
	if (
		value === null ||
		value.status !== "enumerated" ||
		!Array.isArray(value.continuations) ||
		!isHubSha256HexV1(value.requestSha256)
	)
		return null;
	const refs: unknown[] = [];
	const keyDigests = new Set<string>();
	for (const continuation of value.continuations) {
		const ref = projectHubWinnerRecoveryRefTupleV1(continuation);
		if (ref === null) return null;
		if (!Array.isArray(ref[3])) return null;
		const keyDigest = hubCanonicalSha256RefV1(ref[3]);
		if (keyDigests.has(keyDigest)) return null;
		keyDigests.add(keyDigest);
		refs.push(ref);
	}
	return finishHubCanonicalTupleV1(
		value,
		"resultSha256",
		"ref",
		["omp-hub-wait-message-winner-v1", "enumeration", 1, value.requestSha256, refs],
		withDigest,
	);
}

function projectHubTicketAllocationReceiptTupleV1(input: unknown): readonly CanonicalRuntimeValue[] | null {
	if (
		!isStrictContractRecordV1(input, ["core", "receiptSha256"]) ||
		!isHubSha256RefV1(input.receiptSha256) ||
		!isStrictContractRecordV1(input.core, [
			"allocationRequestSha256",
			"ticket",
			"previousSerializerQueueState",
			"registeredSerializerQueueState",
			"previousAllocatedTicketCount",
			"allocatedTicketCount",
			"allocatedAt",
		]) ||
		!isHubSha256RefV1(input.core.allocationRequestSha256) ||
		!isStrictContractIntegerV1(input.core.previousAllocatedTicketCount) ||
		!isStrictContractIntegerV1(input.core.allocatedTicketCount) ||
		input.core.allocatedTicketCount !== input.core.previousAllocatedTicketCount + 1 ||
		!isStrictContractIso8601V1(input.core.allocatedAt)
	)
		return null;
	const ticket = projectHubSerializerTicketTupleV1(input.core.ticket);
	const previous = projectHubSerializerQueueStateTupleV1(input.core.previousSerializerQueueState);
	const registered = projectHubSerializerQueueStateTupleV1(input.core.registeredSerializerQueueState);
	if (
		ticket === null ||
		previous === null ||
		registered === null ||
		!Array.isArray(previous[4]) ||
		!Array.isArray(registered[4]) ||
		!hubCanonicalValuesEqualV1(previous[3], registered[3]) ||
		input.core.previousAllocatedTicketCount !== previous[4].length ||
		input.core.allocatedTicketCount !== registered[4].length ||
		!hubCanonicalValuesEqualV1(registered[4][input.core.previousAllocatedTicketCount], ticket) ||
		previous[5] !== registered[5] ||
		previous[6] !== registered[6] ||
		registered[7] !== input.core.allocatedAt
	)
		return null;
	const tuple: readonly CanonicalRuntimeValue[] = [
		input.core.allocationRequestSha256,
		ticket,
		previous,
		registered,
		input.core.previousAllocatedTicketCount,
		input.core.allocatedTicketCount,
		input.core.allocatedAt,
	];
	return input.receiptSha256 === hubCanonicalSha256RefV1(tuple) ? tuple : null;
}

function projectHubWinnerStartupResumeRequestTupleV1(input: unknown): readonly unknown[] | null {
	if (
		!isStrictContractRecordV1(input, ["enumeration", "requestedAt"]) ||
		!isStrictContractIso8601V1(input.requestedAt)
	)
		return null;
	const enumeration = projectHubWinnerRecoveryEnumerateRequestTupleV1(input.enumeration);
	return enumeration === null
		? null
		: ["omp-hub-wait-message-winner-v1", "winner-startup-resume-request", 1, enumeration, input.requestedAt];
}

function projectHubStartupRecoveredReturnTupleV1(input: unknown, withDigest = true): readonly unknown[] | null {
	const value = hubCanonicalRecordV1(
		input,
		[
			"acknowledgementReceipt",
			"deliveryReceipt",
			"serializerHeadCommitReceipt",
			"ticketAllocationReceipt",
			"advancedSerializerQueueState",
			"nextHeadTicket",
			"recoveredAt",
		],
		"recoverySha256",
		withDigest,
	);
	if (value === null || !isStrictContractIso8601V1(value.recoveredAt)) return null;
	const acknowledgementRecord = isStrictContractRecordV1(value.acknowledgementReceipt, [
		"key",
		"completionRequestSha256",
		"deliveryReceiptSha256",
		"postHookFinalizationSha256",
		"ordinaryPersistenceTicketSha256",
		"ticketAllocationReceiptSha256",
		"ttsrInjectionRegistrationReceiptSha256",
		"primaryCommitJoin",
		"acknowledgementOperationId",
		"acknowledgementRequestSha256",
		"acknowledgedAt",
		"receiptSha256",
	])
		? value.acknowledgementReceipt
		: null;
	if (acknowledgementRecord === null) return null;
	const acknowledgement = projectHubAcknowledgementReceiptTupleV1(acknowledgementRecord);
	const acknowledgementJoin = projectHubPrimaryCommitJoinTupleV1(acknowledgementRecord.primaryCommitJoin);
	const delivery = projectHubWinnerReturnRecordTupleV1("return-delivery-receipt", value.deliveryReceipt, true);
	const head = projectHubSerializerHeadCommitReceiptTupleV1(value.serializerHeadCommitReceipt);
	const allocation = projectHubTicketAllocationReceiptTupleV1(value.ticketAllocationReceipt);
	const advanced = projectHubSerializerQueueStateTupleV1(value.advancedSerializerQueueState);
	const nextHead = value.nextHeadTicket === null ? null : projectHubSerializerTicketTupleV1(value.nextHeadTicket);
	if (
		acknowledgement === null ||
		acknowledgementJoin === null ||
		delivery === null ||
		head === null ||
		allocation === null ||
		advanced === null ||
		(value.nextHeadTicket !== null && nextHead === null) ||
		acknowledgement[5] !== hubCanonicalSha256RefV1(delivery) ||
		acknowledgement[8] !== hubCanonicalSha256RefV1(allocation) ||
		!hubCanonicalValuesEqualV1(acknowledgement[10], acknowledgementJoin) ||
		!hubCanonicalValuesEqualV1(head[9], advanced) ||
		head[17] !== (nextHead === null ? null : hubCanonicalSha256RefV1(nextHead))
	)
		return null;
	return finishHubCanonicalTupleV1(
		value,
		"recoverySha256",
		"ref",
		[
			"omp-hub-wait-message-winner-v1",
			"startup-recovered-return",
			1,
			acknowledgement,
			delivery,
			head,
			allocation,
			advanced,
			nextHead,
			value.recoveredAt,
		],
		withDigest,
	);
}

function projectHubWinnerStartupResumeResultTupleV1(input: unknown): readonly unknown[] | null {
	if (
		!isStrictContractRecordV1(input, ["status", "recoveredReturns", "blockedReturns", "blockedKeys"]) ||
		(input.status !== "resumed" && input.status !== "blocked") ||
		!Array.isArray(input.recoveredReturns) ||
		!Array.isArray(input.blockedReturns) ||
		!Array.isArray(input.blockedKeys)
	)
		return null;
	const recovered: unknown[] = [];
	const blocks: unknown[] = [];
	const keys: unknown[] = [];
	const keyDigests = new Set<string>();
	for (const item of input.recoveredReturns) {
		const tuple = projectHubStartupRecoveredReturnTupleV1(item);
		if (tuple === null) return null;
		recovered.push(tuple);
	}
	for (const item of input.blockedReturns) {
		const tuple = projectHubWinnerReturnRecordTupleV1("return-block", item, true);
		if (tuple === null) return null;
		blocks.push(tuple);
	}
	for (const item of input.blockedKeys) {
		const tuple = projectHubWinnerKeyTupleV1(item);
		if (tuple === null) return null;
		const digest = hubCanonicalSha256RefV1(tuple);
		if (keyDigests.has(digest)) return null;
		keyDigests.add(digest);
		keys.push(tuple);
	}
	if ((input.status === "resumed") !== (blocks.length === 0 && keys.length === 0)) return null;
	return ["omp-hub-wait-message-winner-v1", "winner-startup-resume-result", 1, input.status, recovered, blocks, keys];
}

