function hubCanonicalDigestFieldV1(
	kind: TransientTaskHubWaitMessageCanonicalRecordKindV1,
): readonly [key: string, digestKind: "hex" | "ref"] | null {
	switch (kind) {
		case "winner-key":
		case "send-await-target-session-append-adopt-result":
		case "send-await-target-delivery-consumption-adopt-result":
		case "send-await-outbound-adopt-result":
		case "winner-recovery-ref":
		case "winner-startup-resume-request":
		case "winner-startup-resume-result":
			return null;
		case "current-parent-session-authority":
		case "current-selector-authority":
			return ["authoritySha256", "ref"];
		case "return-target":
			return ["returnTargetSha256", "ref"];
		case "foreground-ttsr-overlay-rule-input":
			return ["ruleInputSha256", "ref"];
		case "foreground-ttsr-overlay-snapshot":
			return ["snapshotSha256", "ref"];
		case "foreground-ttsr-injection-content-plan":
			return ["contentPlanSha256", "ref"];
		case "after-tool-call-plan":
		case "send-await-outbound-plan":
		case "send-await-target-delivery-source-materialization-plan":
		case "send-await-target-delivery-consumption-plan":
			return ["planSha256", "ref"];
		case "send-await-outbound-message":
		case "consumed-message":
			return ["messageSha256", "ref"];
		case "send-await-target-delivery-permit":
		case "send-await-target-delivery-source-materialization-permit":
			return ["permitSha256", "ref"];
		case "selector-install-request":
			return ["selectorInstallRequestSha256", "hex"];
		case "selection-resume-plan":
			return ["resumePlanSha256", "ref"];
		case "preselection-claim":
			return ["claimSha256", "ref"];
		case "winner-capture-request":
			return ["captureRequestSha256", "hex"];
		case "winner-complete-request":
			return ["completionRequestSha256", "hex"];
		case "preselection-recovery-ref":
			return ["refSha256", "ref"];
		case "return-result":
		case "no-selection-return-result":
			return ["resultSha256", "ref"];
		case "no-selection-exit":
			return ["exitSha256", "ref"];
		case "startup-recovered-return":
			return ["recoverySha256", "ref"];
		case "send-await-target-delivery-consumption-state":
		case "send-await-outbound-state":
			return ["stateSha256", "ref"];
		case "send-await-target-delivery-ledger-entry":
			return ["entrySha256", "ref"];
		case "send-await-target-delivery-consumption-block":
		case "return-block":
			return ["blockSha256", "ref"];
		case "send-await-target-session-append-authoritative-absence":
		case "send-await-target-delivery-source-materialization-route-absence":
		case "send-await-target-delivery-consumption-authoritative-absence":
		case "send-await-target-delivery-authoritative-absence":
		case "send-await-outbound-authoritative-absence":
			return ["proofSha256", "ref"];
		case "send-await-target-session-append-inspection":
		case "send-await-target-delivery-consumption-inspection":
		case "send-await-target-delivery-inspection":
		case "send-await-outbound-inspection":
		case "preselection-inspection":
		case "return-delivery-inspection":
		case "return-acknowledgement-inspection":
			return ["inspectionSha256", "ref"];
		case "preselection-enumeration":
		case "winner-recovery-enumeration":
			return ["resultSha256", "ref"];
		case "return-target-registration-receipt":
		case "preselection-adoption-receipt":
		case "return-target-retirement-receipt":
		case "retired-plan-adoption-receipt":
		case "return-delivery-receipt":
		case "return-acknowledgement-receipt":
		case "send-await-outbound-transition-receipt":
		case "send-await-target-session-append-receipt":
		case "send-await-target-delivery-consumption-transition-receipt":
		case "send-await-target-delivery-source-materialization-receipt":
		case "send-await-target-delivery-consumption-receipt":
		case "send-await-outbound-receipt":
			return ["receiptSha256", "ref"];
		case "send-await-outbound-transition-request":
		case "send-await-target-delivery-exact-message-request":
		case "send-await-target-session-append-request":
		case "send-await-target-session-append-inspect-request":
		case "send-await-target-session-append-adopt-request":
		case "send-await-target-failed-observation-request":
		case "send-await-target-delivery-consumption-transition-request":
		case "send-await-target-delivery-consumption-inspect-request":
		case "send-await-target-delivery-consumption-adopt-request":
		case "send-await-target-delivery-inspect-request":
		case "send-await-outbound-inspect-request":
		case "send-await-outbound-adopt-request":
		case "return-target-registration-request":
		case "preselection-enumerate-request":
		case "preselection-inspect-request":
		case "preselection-adopt-request":
		case "preselection-resume-request":
		case "return-target-retirement-request":
		case "retired-plan-adopt-request":
		case "return-delivery-request":
		case "return-delivery-inspect-request":
		case "return-acknowledgement-request":
		case "return-acknowledgement-inspect-request":
		case "winner-recovery-enumerate-request":
			return ["requestSha256", "hex"];
	}
}

export function validateTransientTaskHubWaitMessageCanonicalRecordV1<
	K extends TransientTaskHubWaitMessageCanonicalRecordKindV1,
>(kind: K, input: unknown): input is TransientTaskHubWaitMessageCanonicalRecordSpecV1[K]["record"] {
	return projectHubCanonicalRecordTupleV1(kind, input, true) !== null;
}

export function hashTransientTaskHubWaitMessageCanonicalRecordV1<
	K extends TransientTaskHubWaitMessageCanonicalRecordKindV1,
>(
	kind: K,
	input:
		| TransientTaskHubWaitMessageCanonicalRecordSpecV1[K]["core"]
		| TransientTaskHubWaitMessageCanonicalRecordSpecV1[K]["record"],
): TransientTaskHubWaitMessageCanonicalDigestV1<K>;
export function hashTransientTaskHubWaitMessageCanonicalRecordV1(
	kind: TransientTaskHubWaitMessageCanonicalRecordKindV1,
	input: unknown,
): Sha256Hex | Sha256Ref {
	const tuple =
		projectHubCanonicalRecordTupleV1(kind, input, true) ?? projectHubCanonicalRecordTupleV1(kind, input, false);
	if (tuple === null) throw new TypeError(`Invalid ${kind} canonical record or core`);
	return hubCanonicalDigestFieldV1(kind)?.[1] === "hex"
		? hubCanonicalSha256HexV1(tuple)
		: hubCanonicalSha256RefV1(tuple);
}

export function buildTransientTaskHubWaitMessageCanonicalRecordV1<
	K extends TransientTaskHubWaitMessageCanonicalRecordKindV1,
>(
	kind: K,
	core: TransientTaskHubWaitMessageCanonicalRecordSpecV1[K]["core"],
): TransientTaskHubWaitMessageCanonicalRecordSpecV1[K]["record"];
export function buildTransientTaskHubWaitMessageCanonicalRecordV1(...args: HubWaitCanonicalBuildArgsV1) {
	const [kind, core] = args;
	const tuple = projectHubCanonicalRecordTupleV1(kind, core, false);
	if (tuple === null) throw new TypeError(`Invalid ${kind} canonical core`);
	const field = hubCanonicalDigestFieldV1(kind);
	if (field === null) return Object.freeze({ ...core });
	const digest = field[1] === "hex" ? hubCanonicalSha256HexV1(tuple) : hubCanonicalSha256RefV1(tuple);
	return Object.freeze({ ...core, [field[0]]: digest });
}

export type ConfidentialTransientTaskDetachedSettlementOperationRequestV1 =
	| {
			readonly stage: "settled_result_publication";
			readonly operationId: OperationId;
			readonly requestSha256: Sha256Hex;
			readonly request: Extract<
				ConfidentialTransientTaskDetachedSettlementRequestV1,
				{ readonly terminalStatus: "completed" }
			>;
	  }
	| {
			readonly stage: "settled_result_publication";
			readonly operationId: OperationId;
			readonly requestSha256: Sha256Hex;
			readonly request: Extract<
				ConfidentialTransientTaskDetachedSettlementRequestV1,
				{ readonly terminalStatus: "failed" }
			>;
	  }
	| {
			readonly stage: "settled_result_publication";
			readonly operationId: OperationId;
			readonly requestSha256: Sha256Hex;
			readonly request: ConfidentialTransientTaskDetachedCancellationSettlementRequestV1;
	  }
	| {
			readonly stage: "reservation";
			readonly operationId: OperationId;
			readonly requestSha256: Sha256Hex;
			readonly request: ConfidentialTransientTaskDetachedSettlementReservationRequestV1;
	  }
	| {
			readonly stage: "sink_enqueue";
			readonly operationId: OperationId;
			readonly requestSha256: Sha256Hex;
			readonly request: ConfidentialTransientTaskDetachedSinkEnqueueRequestV1;
	  }
	| {
			readonly stage: "terminal_commit";
			readonly operationId: OperationId;
			readonly requestSha256: Sha256Hex;
			readonly request: ConfidentialTransientTaskDetachedSettlementCommitRequestV1;
	  }
	| {
			readonly stage: "reservation_release";
			readonly operationId: OperationId;
			readonly requestSha256: Sha256Hex;
			readonly request: ConfidentialTransientTaskDetachedSettlementReleaseRequestV1;
	  };

/** Caller-frozen and deterministic; store metadata never participates in attempt identity. */
export interface ConfidentialTransientTaskDetachedSettlementAttemptCoreV1 {
	readonly schemaVersion: 1;
	readonly operation: ConfidentialTransientTaskDetachedSettlementOperationRequestV1;
	readonly operationId: OperationId;
	readonly requestSha256: Sha256Hex;
	readonly preparedAt: ISO8601;
}

export interface ConfidentialTransientTaskDetachedSettlementAttemptV1
	extends ConfidentialTransientTaskDetachedSettlementAttemptCoreV1 {
	/** SHA-256 of detached_settlement_attempt_core. */
	readonly attemptSha256: Sha256Ref;
}

type ConfidentialTransientTaskHubDetachedCurrentAuthorityV1 = Extract<
	ConfidentialTransientTaskDetachedSettlementCurrentAuthorityV1,
	{ readonly kind: "current_owner_epoch" }
>;

export type TransientTaskHubDetachedConsumptionDispositionV1 =
	| "hub_jobs_consumption"
	| "hub_wait_consumption"
	| "hub_cancel_consumption";

type ConfidentialTransientTaskHubDetachedReservationReceiptV1 =
	ConfidentialTransientTaskDetachedSettlementReservationReceiptV1 & {
		readonly disposition: TransientTaskHubDetachedConsumptionDispositionV1;
	};

type ConfidentialTransientTaskHubWaitReservationReceiptV1 =
	ConfidentialTransientTaskDetachedSettlementReservationReceiptV1 & {
		readonly disposition: "hub_wait_consumption";
		readonly hubWaitInvocationId: OperationId;
	};

function sha256CanonicalRuntimeTupleHexV1(tuple: readonly CanonicalRuntimeValue[]): Sha256Hex {
	return createHash("sha256").update(encodeCanonicalRuntimeTupleV1(tuple)).digest("hex") as Sha256Hex;
}

function sha256CanonicalRuntimeTupleRefV1(tuple: readonly CanonicalRuntimeValue[]): Sha256Ref {
	return `sha256:${sha256CanonicalRuntimeTupleHexV1(tuple)}` as Sha256Ref;
}

function canonicalRuntimeTupleJsonUtf8V1(tuple: readonly CanonicalRuntimeValue[]): string {
	return Buffer.from(encodeCanonicalRuntimeTupleV1(tuple)).toString("utf8");
}

function assertCanonicalRuntimeDigestV1(
	actual: Sha256Hex | Sha256Ref,
	expected: Sha256Hex | Sha256Ref,
	label: string,
): void {
	if (actual !== expected) throw new TypeError(`${label} digest mismatch`);
}

function transientTaskResultTargetKeyTupleV1(
	key: TransientTaskResultPublicationTargetKeyV1,
): readonly CanonicalRuntimeValue[] {
	return [
		key.taskId,
		key.runId,
		key.createId,
		key.resultPublicationId,
		key.resultPublicationTargetId,
		key.resultPublicationTargetCleanupId,
	];
}

function transientTaskControllerProofTupleV1(
	proof: TransientTaskControllerAuthorityProofV1,
): readonly CanonicalRuntimeValue[] {
	return [
		proof.taskId,
		proof.runId,
		proof.createId,
		proof.controllerId,
		proof.workspaceId,
		proof.controlHostId,
		proof.controllerEpoch,
		proof.fencingGeneration,
	];
}

function transientTaskCleanupProofTupleV1(
	proof: TransientTaskCleanupAuthorityProofV1,
): readonly CanonicalRuntimeValue[] {
	return [
		proof.taskId,
		proof.runId,
		proof.cleanupId,
		proof.cleanupAuthorityId,
		proof.workspaceId,
		proof.controlHostId,
		proof.cleanupEpoch,
		proof.fencingGeneration,
	];
}

function transientTaskPublicationTargetAuthorityTupleV1(
	authority: ConfidentialTransientTaskResultPublicationTargetAuthorityV1,
): readonly CanonicalRuntimeValue[] {
	switch (authority.kind) {
		case "controller":
			return ["controller", transientTaskControllerProofTupleV1(authority.proof)];
		case "cleanup":
			return ["cleanup", transientTaskCleanupProofTupleV1(authority.proof)];
		case "terminal":
			return ["terminal", [authority.terminalEvidenceId, authority.terminalEvidenceSha256]];
	}
}

function transientTaskEffectIdentityManifestTupleV1(
	manifest: TransientTaskEffectIdentityManifestV1,
): readonly CanonicalRuntimeValue[] {
	return [
		"omp-transient-task-effect-identity-v1",
		"manifest",
		1,
		manifest.taskId,
		manifest.runId,
		manifest.worktreePublicationId,
		manifest.captureMemberNamespaceId,
		manifest.captureMaterializationNamespaceId,
		manifest.messageGenerationNamespaceId,
		manifest.captureSubeffectNamespaceId,
		manifest.semanticMergeStepNamespaceId,
		manifest.semanticMergeSubeffectNamespaceId,
		manifest.bindingOperationNamespaceId,
		manifest.payloadRetentionNamespaceId,
		manifest.parentDeliveryNamespaceId,
	];
}

function transientTaskDetachedEnqueueSelectorTupleV1(input: {
	readonly resultPublicationTargetId: TransientTaskResultPublicationTargetId;
	readonly ownerId: string;
	readonly jobId: string;
	readonly deliveryEpoch: number;
}): readonly CanonicalRuntimeValue[] {
	return [
		"omp-transient-task-parent-delivery-selector-v1",
		"detached-enqueue",
		1,
		input.resultPublicationTargetId,
		input.ownerId,
		input.jobId,
		input.deliveryEpoch,
	];
}

function transientTaskDetachedEnqueueDerivationDescriptorTupleV1(
	descriptor:
		| (ConfidentialTransientTaskParentDeliveryEffectIdentityDerivationDescriptorV1 & {
				readonly derivation: Extract<
					TransientTaskParentDeliveryEffectIdentityDerivationV1,
					{ readonly domain: "detached_enqueue" }
				>;
		  })
		| null,
): readonly CanonicalRuntimeValue[] | null {
	if (descriptor === null) return null;
	const bindingTuple = transientTaskDetachedEnqueueSelectorTupleV1(descriptor.derivation.selectorBinding);
	if (descriptor.derivation.selector.keyUtf8 !== canonicalRuntimeTupleJsonUtf8V1(bindingTuple))
		throw new TypeError("Detached enqueue descriptor selector mismatch");
	const derivationTuple: readonly CanonicalRuntimeValue[] = [
		"omp-transient-task-effect-identity-v1",
		"derive",
		1,
		descriptor.derivation.namespaceId,
		descriptor.derivation.domain,
		[descriptor.derivation.selector.kind, descriptor.derivation.selector.keyUtf8],
	];
	const tuple: readonly CanonicalRuntimeValue[] = [
		"omp-transient-task-effect-identity-v1",
		"parent-delivery-descriptor",
		1,
		derivationTuple,
		bindingTuple,
	];
	assertCanonicalRuntimeDigestV1(
		descriptor.descriptorSha256,
		sha256CanonicalRuntimeTupleRefV1(tuple),
		"Detached enqueue derivation descriptor",
	);
	return tuple;
}

function transientTaskForegroundRenderContextTupleV1(
	context: TransientTaskForegroundSinkRenderContextV1,
): readonly CanonicalRuntimeValue[] {
	return context.documentKind === "single_result"
		? [1, "single_result", context.totalDurationMs, context.resumable]
		: [1, "resultless_terminal"];
}

function transientTaskDetachedFollowUpTupleV1(
	followUp: TransientTaskDetachedFollowUpStateV1,
): readonly CanonicalRuntimeValue[] {
	switch (followUp.kind) {
		case "settled_idle":
			return ["settled_idle", followUp.ircEnabled];
		case "aborted_resumable":
			return ["aborted_resumable", followUp.ircEnabled, followUp.transcript];
		case "aborted_terminal":
			return ["aborted_terminal", followUp.transcript];
		case "resultless_idle":
			return ["resultless_idle", followUp.ircEnabled];
		case "resultless_no_hint":
			return ["resultless_no_hint"];
	}
}

function transientTaskDetachedAsyncFormattingTupleV1(
	formatting: TransientTaskDetachedAsyncFormattingV1,
): readonly CanonicalRuntimeValue[] {
	return [
		formatting.kind,
		formatting.artifactId,
		formatting.artifactUtf8ByteLength,
		formatting.artifactUtf8Sha256,
		formatting.previewCharacterCountLabel,
	];
}

function transientTaskDetachedSinkProjectionTupleV1(
	projection: Extract<
		TransientTaskPerTaskSinkProjectionV1,
		{ readonly kind: "detached_async_result_entry" | "detached_cancelled_job_error" }
	>,
): readonly CanonicalRuntimeValue[] {
	if (projection.kind === "detached_cancelled_job_error")
		return [
			1,
			projection.kind,
			projection.sourceOutcomeDocumentSha256,
			projection.sourceOutcomeDocumentByteLength,
			projection.terminalStatus,
			projection.cancellationKind,
			projection.jobErrorTextUtf8,
			projection.sinkResultUtf8ByteLength,
			projection.sinkResultUtf8Sha256,
		];
	return [
		1,
		projection.kind,
		projection.sourceOutcomeDocumentSha256,
		projection.sourceOutcomeDocumentByteLength,
		transientTaskForegroundRenderContextTupleV1(projection.foregroundRenderContext),
		projection.foregroundResultUtf8,
		transientTaskDetachedFollowUpTupleV1(projection.followUpState),
		projection.followUpHintUtf8,
		projection.asyncResultEntryInputUtf8,
		transientTaskDetachedAsyncFormattingTupleV1(projection.asyncFormatting),
		projection.asyncResultEntryResult,
		projection.sinkResultUtf8ByteLength,
		projection.sinkResultUtf8Sha256,
	];
}

function transientTaskOutcomePayloadRefTupleV1(
	ref: TransientTaskOutcomePayloadRefV1,
): readonly CanonicalRuntimeValue[] {
	return [
		"omp-transient-task-outcome-payload-v1",
		"ref",
		1,
		ref.taskId,
		ref.runId,
		ref.resultPublicationId,
		ref.payloadRole,
		ref.payloadId,
		ref.mediaType,
		ref.byteLength,
		ref.payloadSha256,
	];
}

function transientTaskOutcomePayloadEnvelopeTupleV1(
	payload: TransientTaskOutcomePayloadV1,
): readonly CanonicalRuntimeValue[] {
	return payload.storage === "inline_base64"
		? [
				"inline_base64",
				payload.payloadRole,
				payload.mediaType,
				payload.bytesBase64,
				payload.byteLength,
				payload.payloadSha256,
			]
		: ["opaque_immutable_ref", transientTaskOutcomePayloadRefTupleV1(payload.payloadRef)];
}

function transientTaskParentDeliveryAuthorityTupleV1(
	authority: ConfidentialTransientTaskParentResultDeliveryAuthorityV1,
): readonly CanonicalRuntimeValue[] {
	const manifestTuple = transientTaskEffectIdentityManifestTupleV1(authority.effectIdentityManifest);
	assertCanonicalRuntimeDigestV1(
		authority.effectIdentityManifest.manifestSha256,
		sha256CanonicalRuntimeTupleRefV1(manifestTuple),
		"Task effect identity manifest",
	);
	const targetAuthorityTuple = transientTaskPublicationTargetAuthorityTupleV1(authority.targetAuthority);
	assertCanonicalRuntimeDigestV1(
		authority.targetAuthoritySha256,
		sha256CanonicalRuntimeTupleRefV1(targetAuthorityTuple),
		"Publication target authority",
	);
	return [
		"omp-transient-task-parent-result-delivery-v1",
		"authority",
		1,
		transientTaskResultTargetKeyTupleV1(authority),
		[authority.targetBindingRevision, authority.targetRenewalSequence, authority.targetLiveReceiptSha256],
		manifestTuple,
		targetAuthorityTuple,
		authority.targetAuthoritySha256,
	];
}

type ConfidentialTransientTaskDetachedParentDeliveryRequestV1 =
	ConfidentialTransientTaskDetachedSettlementRequestV1["parentDeliveryRequest"];

function transientTaskDetachedParentDeliveryRequestTupleV1(
	request: ConfidentialTransientTaskDetachedParentDeliveryRequestV1,
): readonly CanonicalRuntimeValue[] {
	if (request.route.kind !== "owner_routed_async_result")
		throw new TypeError("Detached settlement requires owner-routed delivery");
	const authorityTuple = transientTaskParentDeliveryAuthorityTupleV1(request.deliveryAuthority);
	assertCanonicalRuntimeDigestV1(
		request.deliveryAuthoritySha256,
		sha256CanonicalRuntimeTupleRefV1(authorityTuple),
		"Parent delivery authority",
	);
	const descriptorTuple = transientTaskDetachedEnqueueDerivationDescriptorTupleV1(
		request.parentDeliveryEffectDerivationDescriptorOrNull,
	);
	const expectedDeliverySelector = transientTaskDetachedEnqueueSelectorTupleV1({
		resultPublicationTargetId: request.resultPublicationTargetId,
		ownerId: request.route.ownerAgentId,
		jobId: request.route.jobId,
		deliveryEpoch: request.route.deliveryEpoch,
	});
	const expectedDeliveryOperationId = deriveTransientTaskEffectOperationIdV1({
		namespace: "parent_delivery",
		namespaceId: request.deliveryAuthority.effectIdentityManifest.parentDeliveryNamespaceId,
		domain: "detached_enqueue",
		selector: { kind: "key", keyUtf8: canonicalRuntimeTupleJsonUtf8V1(expectedDeliverySelector) },
		selectorBinding: {
			resultPublicationTargetId: request.resultPublicationTargetId,
			ownerId: request.route.ownerAgentId,
			jobId: request.route.jobId,
			deliveryEpoch: request.route.deliveryEpoch,
		},
	});
	if (request.deliveryOperationId !== expectedDeliveryOperationId)
		throw new TypeError("Detached delivery operation identity mismatch");
	const payloadEnvelopeTuple = transientTaskOutcomePayloadEnvelopeTupleV1(request.deliveryPayload);
	assertCanonicalRuntimeDigestV1(
		request.deliveryPayloadEnvelopeSha256,
		sha256CanonicalRuntimeTupleRefV1(payloadEnvelopeTuple),
		"Delivery payload envelope",
	);
	const deliveryPayloadTuple: readonly CanonicalRuntimeValue[] = [
		"omp-transient-task-result-payload-identity-v1",
		1,
		request.deliveryPayloadRole,
		request.deliveryPayloadId,
		request.deliveryPayloadDeleteId,
		request.deliveryPayloadPutReceiptSha256,
		payloadEnvelopeTuple,
		request.deliveryPayloadEnvelopeSha256,
		request.deliveryPayloadSha256,
		request.deliveryPayloadByteLength,
	];
	assertCanonicalRuntimeDigestV1(
		request.deliveryPayloadTupleSha256,
		sha256CanonicalRuntimeTupleRefV1(deliveryPayloadTuple),
		"Delivery payload tuple",
	);
	const parentDeliveryProjection: readonly CanonicalRuntimeValue[] = [
		"owner_routed_async_result",
		request.detachedDeliveryPolicy,
		transientTaskDetachedSinkProjectionTupleV1(request.sinkProjection),
	];
	const tuple: readonly CanonicalRuntimeValue[] = [
		"omp-transient-task-parent-result-delivery-v1",
		"request",
		1,
		transientTaskResultTargetKeyTupleV1(request),
		request.deliveryOperationId,
		descriptorTuple,
		[request.targetBindingRevision, request.targetRenewalSequence, request.targetLiveReceiptSha256],
		authorityTuple,
		request.deliveryAuthoritySha256,
		request.pendingOutcomeSha256,
		request.singleResultCompositionReceiptSha256,
		[
			request.route.kind,
			request.route.ownerAgentId,
			request.route.jobId,
			request.route.deliveryEpoch,
			request.route.sinkLocator,
			request.route.sinkAuthorization,
		],
		parentDeliveryProjection,
		deliveryPayloadTuple,
		request.deliveryPayloadTupleSha256,
	];
	assertCanonicalRuntimeDigestV1(
		request.deliveryRequestSha256,
		sha256CanonicalRuntimeTupleHexV1(tuple),
		"Parent delivery request",
	);
	return tuple;
}

function transientTaskDetachedSettlementIdentityTupleV1(
	identity: TransientTaskDetachedSettlementIdentityV1,
): readonly CanonicalRuntimeValue[] {
	const tuple: readonly CanonicalRuntimeValue[] = [
		"omp-transient-task-detached-settlement-v1",
		"identity",
		1,
		transientTaskResultTargetKeyTupleV1(identity),
		identity.deliveryOperationId,
		identity.ownerId,
		identity.jobId,
		identity.deliveryEpoch,
		identity.deliveryRequestSha256,
		identity.terminalStatus,
		identity.sinkProjectionKind,
		identity.cancellationKind,
		identity.jobErrorTextUtf8Sha256,
		identity.jobErrorTextUtf8ByteLength,
		identity.sinkResultUtf8Sha256,
		identity.sinkResultUtf8ByteLength,
	];
	assertCanonicalRuntimeDigestV1(
		identity.identitySha256,
		sha256CanonicalRuntimeTupleRefV1(tuple),
		"Detached settlement identity",
	);
	return tuple;
}

function transientTaskDetachedSettlementRequestTupleV1(
	settlement: ConfidentialTransientTaskDetachedSettlementRequestV1,
): readonly CanonicalRuntimeValue[] {
	const identityTuple = transientTaskDetachedSettlementIdentityTupleV1(settlement.identity);
	const parentDeliveryTuple = transientTaskDetachedParentDeliveryRequestTupleV1(settlement.parentDeliveryRequest);
	const deliveryAuthorityTuple = transientTaskParentDeliveryAuthorityTupleV1(settlement.deliveryAuthority);
	assertCanonicalRuntimeDigestV1(
		settlement.deliveryAuthoritySha256,
		sha256CanonicalRuntimeTupleRefV1(deliveryAuthorityTuple),
		"Detached settlement delivery authority",
	);
	if (
		settlement.identity.deliveryOperationId !== settlement.parentDeliveryRequest.deliveryOperationId ||
		settlement.identity.deliveryRequestSha256 !== settlement.parentDeliveryRequest.deliveryRequestSha256 ||
		settlement.identity.sinkResultUtf8Sha256 !== settlement.parentDeliveryRequest.sinkResultUtf8Sha256 ||
		settlement.identity.sinkResultUtf8ByteLength !== settlement.parentDeliveryRequest.sinkResultUtf8ByteLength ||
		settlement.terminalStatus !== settlement.identity.terminalStatus
	)
		throw new TypeError("Detached settlement request identity mismatch");
	const tuple: readonly CanonicalRuntimeValue[] = [
		"omp-transient-task-detached-settlement-v1",
		"request",
		1,
		identityTuple,
		settlement.settledResultOperationId,
		settlement.terminalStatus,
		settlement.sinkResultUtf8,
		settlement.jobErrorTextUtf8,
		settlement.settlementPolicy,
		parentDeliveryTuple,
		deliveryAuthorityTuple,
		settlement.deliveryAuthoritySha256,
	];
	assertCanonicalRuntimeDigestV1(
		settlement.settlementRequestSha256,
		sha256CanonicalRuntimeTupleHexV1(tuple),
		"Detached settlement request",
	);
	return tuple;
}

function transientTaskDetachedCurrentAuthorityTupleV1(
	authority: ConfidentialTransientTaskHubDetachedCurrentAuthorityV1,
): readonly CanonicalRuntimeValue[] {
	const identityTuple = transientTaskDetachedSettlementIdentityTupleV1(authority.identity);
	const deliveryAuthorityTuple = transientTaskParentDeliveryAuthorityTupleV1(authority.deliveryAuthority);
	assertCanonicalRuntimeDigestV1(
		authority.deliveryAuthoritySha256,
		sha256CanonicalRuntimeTupleRefV1(deliveryAuthorityTuple),
		"Detached current delivery authority",
	);
	if (authority.ownerId !== authority.identity.ownerId || authority.deliveryEpoch !== authority.identity.deliveryEpoch)
		throw new TypeError("Detached current owner epoch mismatch");
	const tuple: readonly CanonicalRuntimeValue[] = [
		"omp-transient-task-detached-settlement-v1",
		"current-authority",
		1,
		identityTuple,
		authority.deliveryAuthoritySha256,
		authority.settledResultReceiptSha256,
		[authority.kind, authority.ownerId, authority.deliveryEpoch, authority.ownerSinkAuthoritySha256],
	];
	assertCanonicalRuntimeDigestV1(
		authority.currentAuthoritySha256,
		sha256CanonicalRuntimeTupleRefV1(tuple),
		"Detached current authority",
	);
	return tuple;
}

function assertHubDetachedAuthorityJoinV1(
	settlement: ConfidentialTransientTaskDetachedSettlementRequestV1,
	currentAuthority: ConfidentialTransientTaskHubDetachedCurrentAuthorityV1,
): void {
	if (
		settlement.identity.identitySha256 !== currentAuthority.identity.identitySha256 ||
		settlement.deliveryAuthoritySha256 !== currentAuthority.deliveryAuthoritySha256 ||
		settlement.identity.ownerId !== currentAuthority.ownerId ||
		settlement.identity.deliveryEpoch !== currentAuthority.deliveryEpoch
	)
		throw new TypeError("Detached settlement/current authority join mismatch");
}

function deriveHubDetachedEffectOperationIdV1(
	input:
		| {
				readonly settlement: ConfidentialTransientTaskDetachedSettlementRequestV1;
				readonly domain: "detached_reservation";
				readonly selectorTuple: readonly CanonicalRuntimeValue[];
				readonly selectorBinding: Extract<
					TransientTaskParentDeliveryEffectIdentityDerivationV1,
					{ readonly domain: "detached_reservation" }
				>["selectorBinding"];
		  }
		| {
				readonly settlement: ConfidentialTransientTaskDetachedSettlementRequestV1;
				readonly domain: "detached_suppression";
				readonly selectorTuple: readonly CanonicalRuntimeValue[];
				readonly selectorBinding: Extract<
					TransientTaskParentDeliveryEffectIdentityDerivationV1,
					{ readonly domain: "detached_suppression" }
				>["selectorBinding"];
		  }
		| {
				readonly settlement: ConfidentialTransientTaskDetachedSettlementRequestV1;
				readonly domain: "detached_consumption";
				readonly selectorTuple: readonly CanonicalRuntimeValue[];
				readonly selectorBinding: Extract<
					TransientTaskParentDeliveryEffectIdentityDerivationV1,
					{ readonly domain: "detached_consumption" }
				>["selectorBinding"];
		  }
		| {
				readonly settlement: ConfidentialTransientTaskDetachedSettlementRequestV1;
				readonly domain: "detached_reservation_release";
				readonly selectorTuple: readonly CanonicalRuntimeValue[];
				readonly selectorBinding: Extract<
					TransientTaskParentDeliveryEffectIdentityDerivationV1,
					{ readonly domain: "detached_reservation_release" }
				>["selectorBinding"];
		  },
): OperationId {
	const selector = { kind: "key", keyUtf8: canonicalRuntimeTupleJsonUtf8V1(input.selectorTuple) } as const;
	switch (input.domain) {
		case "detached_reservation":
			return deriveTransientTaskEffectOperationIdV1({
				namespace: "parent_delivery",
				namespaceId: input.settlement.deliveryAuthority.effectIdentityManifest.parentDeliveryNamespaceId,
				domain: input.domain,
				selector,
				selectorBinding: input.selectorBinding,
			});
		case "detached_suppression":
			return deriveTransientTaskEffectOperationIdV1({
				namespace: "parent_delivery",
				namespaceId: input.settlement.deliveryAuthority.effectIdentityManifest.parentDeliveryNamespaceId,
				domain: input.domain,
				selector,
				selectorBinding: input.selectorBinding,
			});
		case "detached_consumption":
			return deriveTransientTaskEffectOperationIdV1({
				namespace: "parent_delivery",
				namespaceId: input.settlement.deliveryAuthority.effectIdentityManifest.parentDeliveryNamespaceId,
				domain: input.domain,
				selector,
				selectorBinding: input.selectorBinding,
			});
		case "detached_reservation_release":
			return deriveTransientTaskEffectOperationIdV1({
				namespace: "parent_delivery",
				namespaceId: input.settlement.deliveryAuthority.effectIdentityManifest.parentDeliveryNamespaceId,
				domain: input.domain,
				selector,
				selectorBinding: input.selectorBinding,
			});
	}
}

function transientTaskDetachedOperationTupleV1(
	operation: ConfidentialTransientTaskDetachedSettlementOperationRequestV1,
	stageRequestTuple: readonly CanonicalRuntimeValue[],
): readonly CanonicalRuntimeValue[] {
	return [
		"omp-transient-task-detached-settlement-v1",
		"operation",
		1,
		operation.stage,
		operation.operationId,
		operation.requestSha256,
		stageRequestTuple,
	];
}

function deriveHubDetachedAttemptEnvelopeV1<
	TOperation extends Extract<
		ConfidentialTransientTaskDetachedSettlementOperationRequestV1,
		{ readonly stage: "reservation" | "terminal_commit" | "reservation_release" }
	>,
>(
	operation: TOperation,
	stageRequestTuple: readonly CanonicalRuntimeValue[],
	preparedAt: ISO8601,
): {
	readonly attempt: Omit<ConfidentialTransientTaskDetachedSettlementAttemptV1, "operation"> & {
		readonly operation: TOperation;
	};
	readonly inspectRequest: TransientTaskDetachedSettlementInspectRequestV1;
} {
	const operationTuple = transientTaskDetachedOperationTupleV1(operation, stageRequestTuple);
	const attemptCore: Omit<ConfidentialTransientTaskDetachedSettlementAttemptCoreV1, "operation"> & {
		readonly operation: TOperation;
	} = {
		schemaVersion: 1,
		operation,
		operationId: operation.operationId,
		requestSha256: operation.requestSha256,
		preparedAt,
	};
	const attemptCoreTuple: readonly CanonicalRuntimeValue[] = [
		"omp-transient-task-detached-settlement-v1",
		"attempt-core",
		1,
		operationTuple,
		attemptCore.operationId,
		attemptCore.requestSha256,
		attemptCore.preparedAt,
	];
	const attempt = { ...attemptCore, attemptSha256: sha256CanonicalRuntimeTupleRefV1(attemptCoreTuple) };
	return {
		attempt,
		inspectRequest: {
			identitySha256: operation.request.settlement.identity.identitySha256,
			stage: operation.stage,
			operationId: operation.operationId,
			expectedRequestSha256: operation.requestSha256,
			expectedAttemptSha256: attempt.attemptSha256,
		},
	};
}

export type TransientTaskHubDetachedReservationAttemptInputV1 =
	| {
			readonly settlement: ConfidentialTransientTaskDetachedSettlementRequestV1;
			readonly currentAuthority: ConfidentialTransientTaskHubDetachedCurrentAuthorityV1;
			readonly disposition: "hub_jobs_consumption" | "hub_cancel_consumption";
			readonly preparedAt: ISO8601;
	  }
	| {
			readonly settlement: ConfidentialTransientTaskDetachedSettlementRequestV1;
			readonly currentAuthority: ConfidentialTransientTaskHubDetachedCurrentAuthorityV1;
			readonly disposition: "hub_wait_consumption";
			readonly hubWaitInvocationId: OperationId;
			readonly preparedAt: ISO8601;
	  };

export interface TransientTaskHubDetachedReservationAttemptDerivationV1 {
	readonly request: ConfidentialTransientTaskDetachedSettlementReservationRequestV1 & {
		readonly disposition: TransientTaskHubDetachedConsumptionDispositionV1;
	};
	readonly operation: Extract<
		ConfidentialTransientTaskDetachedSettlementOperationRequestV1,
		{ readonly stage: "reservation" }
	>;
	readonly attempt: ConfidentialTransientTaskDetachedSettlementAttemptV1;
	readonly inspectRequest: TransientTaskDetachedSettlementInspectRequestV1;
}

export function deriveTransientTaskHubDetachedReservationAttemptV1(
	input: TransientTaskHubDetachedReservationAttemptInputV1,
): TransientTaskHubDetachedReservationAttemptDerivationV1 {
	assertHubDetachedAuthorityJoinV1(input.settlement, input.currentAuthority);
	const settlementTuple = transientTaskDetachedSettlementRequestTupleV1(input.settlement);
	const currentAuthorityTuple = transientTaskDetachedCurrentAuthorityTupleV1(input.currentAuthority);
	const reservationSelectorBinding: Extract<
		TransientTaskParentDeliveryEffectIdentityDerivationV1,
		{ readonly domain: "detached_reservation" }
	>["selectorBinding"] =
		input.disposition === "hub_wait_consumption"
			? {
					identitySha256: input.settlement.identity.identitySha256,
					disposition: input.disposition,
					hubWaitInvocationId: input.hubWaitInvocationId,
				}
			: {
					identitySha256: input.settlement.identity.identitySha256,
					disposition: input.disposition,
					hubWaitInvocationId: null,
				};
	const reservationId = deriveHubDetachedEffectOperationIdV1({
		settlement: input.settlement,
		domain: "detached_reservation",
		selectorTuple: [
			"omp-transient-task-parent-delivery-selector-v1",
			"detached-reservation",
			1,
			reservationSelectorBinding.identitySha256,
			reservationSelectorBinding.disposition,
			reservationSelectorBinding.hubWaitInvocationId,
		],
		selectorBinding: reservationSelectorBinding,
	});
	const suppressionSelectorBinding: Extract<
		TransientTaskParentDeliveryEffectIdentityDerivationV1,
		{ readonly domain: "detached_suppression" }
	>["selectorBinding"] =
		input.disposition === "hub_wait_consumption"
			? {
					identitySha256: input.settlement.identity.identitySha256,
					consumer: "hub_wait",
					hubWaitInvocationId: input.hubWaitInvocationId,
				}
			: {
					identitySha256: input.settlement.identity.identitySha256,
					consumer: input.disposition === "hub_jobs_consumption" ? "hub_jobs" : "hub_cancel",
					hubWaitInvocationId: null,
				};
	const suppressionOperationId = deriveHubDetachedEffectOperationIdV1({
		settlement: input.settlement,
		domain: "detached_suppression",
		selectorTuple: [
			"omp-transient-task-parent-delivery-selector-v1",
			"detached-suppression",
			1,
			suppressionSelectorBinding.identitySha256,
			suppressionSelectorBinding.consumer,
			suppressionSelectorBinding.hubWaitInvocationId,
		],
		selectorBinding: suppressionSelectorBinding,
	});
	const requestCore =
		input.disposition === "hub_wait_consumption"
			? {
					settlement: input.settlement,
					currentAuthority: input.currentAuthority,
					reservationId,
					disposition: input.disposition,
					suppressionOperationId,
					hubWaitInvocationId: input.hubWaitInvocationId,
				}
			: {
					settlement: input.settlement,
					currentAuthority: input.currentAuthority,
					reservationId,
					disposition: input.disposition,
					suppressionOperationId,
				};
	const dispositionSpecificTuple: readonly CanonicalRuntimeValue[] =
		input.disposition === "hub_wait_consumption"
			? [suppressionOperationId, input.hubWaitInvocationId]
			: [suppressionOperationId];
	const requestTuple: readonly CanonicalRuntimeValue[] = [
		"omp-transient-task-detached-settlement-v1",
		"reserve",
		1,
		settlementTuple,
		currentAuthorityTuple,
		reservationId,
		input.disposition,
		dispositionSpecificTuple,
	];
	const request: ConfidentialTransientTaskDetachedSettlementReservationRequestV1 & {
		readonly disposition: TransientTaskHubDetachedConsumptionDispositionV1;
	} = { ...requestCore, reservationRequestSha256: sha256CanonicalRuntimeTupleHexV1(requestTuple) };
	const operation: Extract<
		ConfidentialTransientTaskDetachedSettlementOperationRequestV1,
		{ readonly stage: "reservation" }
	> = { stage: "reservation", operationId: reservationId, requestSha256: request.reservationRequestSha256, request };
	return { request, operation, ...deriveHubDetachedAttemptEnvelopeV1(operation, requestTuple, input.preparedAt) };
}

export interface TransientTaskHubDetachedCommitAttemptInputV1 {
	readonly settlement: ConfidentialTransientTaskDetachedSettlementRequestV1;
	readonly currentAuthority: ConfidentialTransientTaskHubDetachedCurrentAuthorityV1;
	readonly reservation: ConfidentialTransientTaskHubDetachedReservationReceiptV1;
	readonly preparedAt: ISO8601;
}

export interface TransientTaskHubDetachedCommitAttemptDerivationV1 {
	readonly request: ConfidentialTransientTaskDetachedSettlementCommitRequestV1 & {
		readonly disposition: TransientTaskHubDetachedConsumptionDispositionV1;
		readonly sinkReceipt: null;
		readonly sinkReceiptSha256: null;
	};
	readonly operation: Extract<
		ConfidentialTransientTaskDetachedSettlementOperationRequestV1,
		{ readonly stage: "terminal_commit" }
	>;
	readonly attempt: ConfidentialTransientTaskDetachedSettlementAttemptV1;
	readonly inspectRequest: TransientTaskDetachedSettlementInspectRequestV1;
}

export function deriveTransientTaskHubDetachedCommitAttemptV1(
	input: TransientTaskHubDetachedCommitAttemptInputV1,
): TransientTaskHubDetachedCommitAttemptDerivationV1 {
	assertHubDetachedAuthorityJoinV1(input.settlement, input.currentAuthority);
	if (
		input.reservation.identity.identitySha256 !== input.settlement.identity.identitySha256 ||
		input.reservation.currentAuthoritySha256 !== input.currentAuthority.currentAuthoritySha256
	)
		throw new TypeError("Detached Hub reservation join mismatch");
	const selectorBinding = {
		identitySha256: input.settlement.identity.identitySha256,
		reservationId: input.reservation.reservationId,
		disposition: input.reservation.disposition,
	} satisfies Extract<
		TransientTaskParentDeliveryEffectIdentityDerivationV1,
		{ readonly domain: "detached_consumption" }
	>["selectorBinding"];
	const commitOperationId = deriveHubDetachedEffectOperationIdV1({
		settlement: input.settlement,
		domain: "detached_consumption",
		selectorTuple: [
			"omp-transient-task-parent-delivery-selector-v1",
			"detached-consumption",
			1,
			selectorBinding.identitySha256,
			selectorBinding.reservationId,
			selectorBinding.disposition,
		],
		selectorBinding,
	});
	const requestCore = {
		settlement: input.settlement,
		currentAuthority: input.currentAuthority,
		reservation: input.reservation,
		commitOperationId,
		disposition: input.reservation.disposition,
		sinkReceipt: null,
		sinkReceiptSha256: null,
	} as const;
	const requestTuple: readonly CanonicalRuntimeValue[] = [
		"omp-transient-task-detached-settlement-v1",
		"commit",
		1,
		transientTaskDetachedSettlementRequestTupleV1(input.settlement),
		transientTaskDetachedCurrentAuthorityTupleV1(input.currentAuthority),
		input.reservation.receiptSha256,
		commitOperationId,
		input.reservation.disposition,
		null,
	];
	const request: ConfidentialTransientTaskDetachedSettlementCommitRequestV1 & {
		readonly disposition: TransientTaskHubDetachedConsumptionDispositionV1;
		readonly sinkReceipt: null;
		readonly sinkReceiptSha256: null;
	} = { ...requestCore, commitRequestSha256: sha256CanonicalRuntimeTupleHexV1(requestTuple) };
	const operation: Extract<
		ConfidentialTransientTaskDetachedSettlementOperationRequestV1,
		{ readonly stage: "terminal_commit" }
	> = {
		stage: "terminal_commit",
		operationId: commitOperationId,
		requestSha256: request.commitRequestSha256,
		request,
	};
	return { request, operation, ...deriveHubDetachedAttemptEnvelopeV1(operation, requestTuple, input.preparedAt) };
}

export interface TransientTaskHubDetachedReleaseAttemptInputV1 {
	readonly settlement: ConfidentialTransientTaskDetachedSettlementRequestV1;
	readonly currentAuthority: ConfidentialTransientTaskHubDetachedCurrentAuthorityV1;
	readonly reservation: ConfidentialTransientTaskHubWaitReservationReceiptV1;
	readonly reason: Exclude<
		ConfidentialTransientTaskDetachedSettlementReleaseRequestV1["reason"],
		"sink_proven_not_applied"
	>;
	readonly preparedAt: ISO8601;
}

export interface TransientTaskHubDetachedReleaseAttemptDerivationV1 {
	readonly request: ConfidentialTransientTaskDetachedSettlementReleaseRequestV1 & {
		readonly reservation: ConfidentialTransientTaskHubWaitReservationReceiptV1;
	};
	readonly operation: Extract<
		ConfidentialTransientTaskDetachedSettlementOperationRequestV1,
		{ readonly stage: "reservation_release" }
	>;
	readonly attempt: ConfidentialTransientTaskDetachedSettlementAttemptV1;
	readonly inspectRequest: TransientTaskDetachedSettlementInspectRequestV1;
}

export function deriveTransientTaskHubDetachedReleaseAttemptV1(
	input: TransientTaskHubDetachedReleaseAttemptInputV1,
): TransientTaskHubDetachedReleaseAttemptDerivationV1 {
	assertHubDetachedAuthorityJoinV1(input.settlement, input.currentAuthority);
	if (
		input.reservation.identity.identitySha256 !== input.settlement.identity.identitySha256 ||
		input.reservation.currentAuthoritySha256 !== input.currentAuthority.currentAuthoritySha256 ||
		input.reservation.suppression.consumer !== "hub_wait"
	)
		throw new TypeError("Detached Hub wait reservation join mismatch");
	const selectorBinding = {
		identitySha256: input.settlement.identity.identitySha256,
		reservationId: input.reservation.reservationId,
		reason: input.reason,
	} satisfies Extract<
		TransientTaskParentDeliveryEffectIdentityDerivationV1,
		{ readonly domain: "detached_reservation_release" }
	>["selectorBinding"];
	const releaseOperationId = deriveHubDetachedEffectOperationIdV1({
		settlement: input.settlement,
		domain: "detached_reservation_release",
		selectorTuple: [
			"omp-transient-task-parent-delivery-selector-v1",
			"detached-reservation-release",
			1,
			selectorBinding.identitySha256,
			selectorBinding.reservationId,
			selectorBinding.reason,
		],
		selectorBinding,
	});
	const requestTuple: readonly CanonicalRuntimeValue[] = [
		"omp-transient-task-detached-settlement-v1",
		"release",
		1,
		transientTaskDetachedSettlementRequestTupleV1(input.settlement),
		transientTaskDetachedCurrentAuthorityTupleV1(input.currentAuthority),
		input.reservation.receiptSha256,
		releaseOperationId,
		input.reason,
	];
	const request: ConfidentialTransientTaskDetachedSettlementReleaseRequestV1 & {
		readonly reservation: ConfidentialTransientTaskHubWaitReservationReceiptV1;
	} = {
		settlement: input.settlement,
		currentAuthority: input.currentAuthority,
		reservation: input.reservation,
		releaseOperationId,
		reason: input.reason,
		releaseRequestSha256: sha256CanonicalRuntimeTupleHexV1(requestTuple),
	};
	const operation: Extract<
		ConfidentialTransientTaskDetachedSettlementOperationRequestV1,
		{ readonly stage: "reservation_release" }
	> = {
		stage: "reservation_release",
		operationId: releaseOperationId,
		requestSha256: request.releaseRequestSha256,
		request,
	};
	return { request, operation, ...deriveHubDetachedAttemptEnvelopeV1(operation, requestTuple, input.preparedAt) };
}

/** The only detached attempt an AsyncJob recovery row may retain. */
export type ConfidentialTransientTaskDetachedSettledResultAttemptV1 = Omit<
	ConfidentialTransientTaskDetachedSettlementAttemptV1,
	"operation"
> & {
	readonly operation: Extract<
		ConfidentialTransientTaskDetachedSettlementOperationRequestV1,
		{ readonly stage: "settled_result_publication" }
	>;
};
export type ConfidentialTransientTaskDetachedCancellationSettledResultAttemptV1 = Omit<
	ConfidentialTransientTaskDetachedSettlementAttemptV1,
	"operation"
> & {
	readonly operation: Extract<
		ConfidentialTransientTaskDetachedSettlementOperationRequestV1,
		{
			readonly stage: "settled_result_publication";
			readonly request: { readonly terminalStatus: "cancelled" };
		}
	>;
};

export interface TransientTaskDetachedSettlementNotAppliedReceiptV1 {
	readonly schemaVersion: 1;
	readonly identitySha256: Sha256Ref;
	readonly stage: ConfidentialTransientTaskDetachedSettlementOperationRequestV1["stage"];
	readonly operationId: OperationId;
	readonly requestSha256: Sha256Hex;
	readonly attemptSha256: Sha256Ref;
	/** Store-generated receipt metadata; excluded from attemptSha256. */
	readonly storedAt: ISO8601;
	readonly receiptSha256: Sha256Ref;
}

export interface ConfidentialTransientTaskDetachedSettlementPrepareRequestV1 {
	readonly attempt: ConfidentialTransientTaskDetachedSettlementAttemptV1;
}

export type TransientTaskDetachedSettlementPrepareResultV1 =
	| {
			readonly status: "prepared" | "already_prepared";
			readonly attempt: ConfidentialTransientTaskDetachedSettlementAttemptV1;
			readonly notAppliedReceipt: TransientTaskDetachedSettlementNotAppliedReceiptV1;
	  }
	| {
			readonly status: "prepare_outcome_unknown";
			readonly operationId: OperationId;
			readonly requestSha256: Sha256Hex;
			readonly attemptSha256: Sha256Ref;
	  }
	| {
			readonly status: "identity_conflict" | "request_conflict" | "attempt_conflict" | "invalid";
	  };

/** Every external effect carries the exact caller-known attempt and not-applied receipt digests. */
export interface ConfidentialTransientTaskDetachedSettlementEffectRequestV1 {
	readonly operation: ConfidentialTransientTaskDetachedSettlementOperationRequestV1;
	readonly expectedAttemptSha256: Sha256Ref;
	readonly expectedNotAppliedReceiptSha256: Sha256Ref;
}

export type ConfidentialTransientTaskDetachedSettlementOperationReceiptV1 =
	| TransientTaskDetachedSettledResultPublicationReceiptV1
	| ConfidentialTransientTaskDetachedSettlementReservationReceiptV1
	| Extract<ConfidentialTransientTaskParentResultSinkReceiptV1, { routeKind: "owner_routed_async_result" }>
	| ConfidentialTransientTaskDetachedSettlementTerminalReceiptV1
	| ConfidentialTransientTaskDetachedSettlementReleaseReceiptV1;

/** Public side-effect-free, route-free inspection key; exact bytes and authority never project here. */
export interface TransientTaskDetachedSettlementInspectRequestV1 {
	readonly identitySha256: Sha256Ref;
	readonly stage: ConfidentialTransientTaskDetachedSettlementOperationRequestV1["stage"];
	readonly operationId: OperationId;
	readonly expectedRequestSha256: Sha256Hex;
	readonly expectedAttemptSha256: Sha256Ref;
}
export interface TransientTaskDetachedCancellationSettlementInspectRequestV1
	extends TransientTaskDetachedSettlementInspectRequestV1 {
	readonly stage: "settled_result_publication";
	readonly expectedTerminalStatus: "cancelled";
	readonly expectedCancellationKind: "detached_pre_execution_abort";
	readonly expectedJobErrorTextUtf8Sha256: Sha256Ref;
	readonly expectedJobErrorTextUtf8ByteLength: number;
	readonly expectedCancellationIdentitySha256: Sha256Ref;
}

export type TransientTaskDetachedSettlementInspectResultV1 =
	| {
			readonly status: "absent";
			readonly identitySha256: Sha256Ref;
			readonly stage: ConfidentialTransientTaskDetachedSettlementOperationRequestV1["stage"];
			readonly operationId: OperationId;
			readonly requestSha256: Sha256Hex;
			readonly attemptSha256: Sha256Ref;
	  }
	| {
			readonly status: "not_applied" | "outcome_unknown";
			readonly identitySha256: Sha256Ref;
			readonly stage: ConfidentialTransientTaskDetachedSettlementOperationRequestV1["stage"];
			readonly operationId: OperationId;
			readonly attemptSha256: Sha256Ref;
			readonly notAppliedReceiptSha256: Sha256Ref;
			readonly requestSha256: Sha256Hex;
	  }
	| {
			readonly status: "matching";
			readonly identitySha256: Sha256Ref;
			readonly stage: ConfidentialTransientTaskDetachedSettlementOperationRequestV1["stage"];
			readonly operationId: OperationId;
			readonly attemptSha256: Sha256Ref;
			readonly notAppliedReceiptSha256: Sha256Ref;
			readonly receiptSha256: Sha256Ref;
			readonly requestSha256: Sha256Hex;
	  }
	| { readonly status: "conflict" | "invalid" };

export interface ConfidentialTransientTaskDetachedSettlementAdoptRequestBaseV1
	extends TransientTaskDetachedSettlementInspectRequestV1 {
	readonly expectedIdentity: TransientTaskDetachedSettlementIdentityV1;
	readonly expectedOperation: ConfidentialTransientTaskDetachedSettlementOperationRequestV1;
	readonly expectedAttempt: ConfidentialTransientTaskDetachedSettlementAttemptV1;
	readonly expectedNotAppliedReceiptSha256: Sha256Ref;
	readonly expectedReceiptSha256: Sha256Ref | null;
}

export type ConfidentialTransientTaskDetachedSettlementAdoptRequestV1 =
	| (ConfidentialTransientTaskDetachedSettlementAdoptRequestBaseV1 & {
			readonly expectedOperation: Exclude<
				Extract<
					ConfidentialTransientTaskDetachedSettlementOperationRequestV1,
					{ stage: "settled_result_publication" }
				>,
				{ readonly request: { readonly terminalStatus: "cancelled" } }
			>;
			readonly expectedCurrentAuthority: null;
	  })
	| ConfidentialTransientTaskDetachedCancellationSettlementAdoptRequestV1
	| (ConfidentialTransientTaskDetachedSettlementAdoptRequestBaseV1 & {
			readonly expectedOperation: Exclude<
				ConfidentialTransientTaskDetachedSettlementOperationRequestV1,
				{ stage: "settled_result_publication" }
			>;
			readonly expectedCurrentAuthority: ConfidentialTransientTaskDetachedSettlementCurrentAuthorityV1;
	  });

export interface ConfidentialTransientTaskDetachedCancellationSettlementAdoptRequestV1
	extends ConfidentialTransientTaskDetachedSettlementAdoptRequestBaseV1 {
	readonly stage: "settled_result_publication";
	readonly expectedIdentity: TransientTaskDetachedCancellationSettlementIdentityV1;
	readonly expectedOperation: Extract<
		ConfidentialTransientTaskDetachedSettlementOperationRequestV1,
		{
			readonly stage: "settled_result_publication";
			readonly request: { readonly terminalStatus: "cancelled" };
		}
	>;
	readonly expectedAttempt: ConfidentialTransientTaskDetachedCancellationSettledResultAttemptV1;
	readonly expectedCurrentAuthority: null;
	readonly expectedTerminalStatus: "cancelled";
	readonly expectedJobErrorTextUtf8Sha256: Sha256Ref;
	readonly expectedJobErrorTextUtf8ByteLength: number;
	readonly expectedCancellationIdentitySha256: Sha256Ref;
}

export type ConfidentialTransientTaskDetachedSettlementAdoptResultV1 =
	| {
			readonly status: "adopted";
			readonly attempt: ConfidentialTransientTaskDetachedSettlementAttemptV1;
			readonly receipt: ConfidentialTransientTaskDetachedSettlementOperationReceiptV1;
	  }
	| {
			readonly status: "not_applied";
			readonly attempt: ConfidentialTransientTaskDetachedSettlementAttemptV1;
			readonly notAppliedReceipt: TransientTaskDetachedSettlementNotAppliedReceiptV1;
	  }
	| {
			readonly status: "outcome_unknown";
			readonly attempt: ConfidentialTransientTaskDetachedSettlementAttemptV1;
			readonly notAppliedReceipt: TransientTaskDetachedSettlementNotAppliedReceiptV1;
	  }
	| {
			readonly status: "absent" | "authority_lost" | "conflict" | "invalid";
	  };
export type ConfidentialTransientTaskDetachedCancellationSettlementAdoptResultV1 =
	| {
			readonly status: "adopted";
			readonly attempt: ConfidentialTransientTaskDetachedCancellationSettledResultAttemptV1;
			readonly receipt: TransientTaskDetachedSettledResultPublicationReceiptV1 & {
				readonly identity: TransientTaskDetachedCancellationSettlementIdentityV1;
			};
	  }
	| {
			readonly status: "not_applied" | "outcome_unknown";
			readonly attempt: ConfidentialTransientTaskDetachedCancellationSettledResultAttemptV1;
			readonly notAppliedReceipt: TransientTaskDetachedSettlementNotAppliedReceiptV1;
	  }
	| { readonly status: "absent" | "authority_lost" | "conflict" | "invalid" };

