export type TransientTaskForegroundSourceProjectionGoldenVectorCaseV1 =
	| "valid_safe_json_and_declared_own_undefined"
	| "bigint_value_rejected"
	| "symbol_value_rejected"
	| "symbol_key_rejected"
	| "function_value_rejected"
	| "sparse_array_rejected"
	| "exotic_prototype_rejected"
	| "cycle_rejected"
	| "accessor_rejected_without_invocation"
	| "proxy_rejected_without_trap_escape"
	| "lone_surrogate_value_rejected"
	| "lone_surrogate_key_rejected"
	| "nan_rejected"
	| "positive_infinity_rejected"
	| "negative_infinity_rejected"
	| "negative_zero_rejected"
	| "source_snapshot_json_encoding_failure"
	| "wire_json_encoding_failure";

/** In-memory fixture: hostile source members need not themselves be serializable. */
interface ConfidentialTransientTaskForegroundSourceProjectionGoldenVectorBaseV1 {
	readonly schemaVersion: 1;
	readonly source: unknown;
	readonly expectedLiveProjectionSha256: Sha256Ref;
	readonly expectedRestartProjectionSha256: Sha256Ref;
	readonly expectedLiveAndRestartValidationEqual: true;
}

interface ConfidentialTransientTaskForegroundSourceProjectionRejectedExpectationV1
	extends ConfidentialTransientTaskForegroundSourceProjectionGoldenVectorBaseV1 {
	readonly expectedStatus: "rejected";
	readonly expectedSourceDisposition: "fixed_tool_error";
	readonly expectedNoHandoffReason: "source_value_unrepresentable";
	readonly expectedToolErrorCode: "foreground_source_value_unrepresentable";
	readonly expectedToolResultText: typeof TRANSIENT_TASK_FOREGROUND_SOURCE_VALUE_TOOL_ERROR_TEXT_V1;
	readonly expectedForegroundHandoffCreated: false;
	readonly expectedBeforeReturnRecordCreated: false;
}

export type ConfidentialTransientTaskForegroundSourceProjectionGoldenVectorForCaseV1<
	TCase extends TransientTaskForegroundSourceProjectionGoldenVectorCaseV1,
> = TCase extends "valid_safe_json_and_declared_own_undefined"
	? ConfidentialTransientTaskForegroundSourceProjectionGoldenVectorBaseV1 & {
			readonly case: TCase;
			readonly injectedEncodingFailure: "none";
			readonly expectedStatus: "projected";
			readonly expectedSourceDisposition: "unchanged_valid";
			readonly expectedNoHandoffReason: null;
			readonly expectedToolErrorCode: null;
			readonly expectedToolResultText: null;
			readonly expectedForegroundHandoffCreated: true;
			readonly expectedBeforeReturnRecordCreated: true;
			readonly expectedReturnedSourceResultSameReference: true;
			readonly expectedAcyclicAliasAccepted: true;
			readonly expectedTaggedAliasSubtreesDuplicatedByValueAndByteIdentical: true;
			readonly expectedWireAliasSubtreesDuplicatedByValueAndByteIdentical: true;
			readonly expectedSanitizerInputContainsAnsiC0CrC1: true;
			readonly expectedWireTextEqualsSanitizeTextOfSourceText: true;
			readonly expectedSourceTextSignatureRetainedInTaggedSnapshot: true;
			readonly expectedWireTextSignatureDropped: true;
			readonly expectedSourceSnapshotAndWireUtf8Distinct: true;
			readonly expectedSourceSnapshotUtf8: string;
			readonly expectedWireUtf8: string;
			readonly expectedRestartSourceSnapshotUtf8: string;
			readonly expectedRestartWireUtf8: string;
			readonly expectedLiveAndRestartSourceSnapshotUtf8ByteIdentical: true;
			readonly expectedLiveAndRestartWireUtf8ByteIdentical: true;
		}
	: TCase extends "source_snapshot_json_encoding_failure"
		? ConfidentialTransientTaskForegroundSourceProjectionRejectedExpectationV1 & {
				readonly case: TCase;
				readonly injectedEncodingFailure: "source_snapshot";
			}
		: TCase extends "wire_json_encoding_failure"
			? ConfidentialTransientTaskForegroundSourceProjectionRejectedExpectationV1 & {
					readonly case: TCase;
					readonly injectedEncodingFailure: "wire";
				}
			: ConfidentialTransientTaskForegroundSourceProjectionRejectedExpectationV1 & {
					readonly case: TCase;
					readonly injectedEncodingFailure: "none";
				};

export type ConfidentialTransientTaskForegroundSourceProjectionGoldenVectorV1 = {
	readonly [TCase in TransientTaskForegroundSourceProjectionGoldenVectorCaseV1]: ConfidentialTransientTaskForegroundSourceProjectionGoldenVectorForCaseV1<TCase>;
}[TransientTaskForegroundSourceProjectionGoldenVectorCaseV1];

