/**
 * Stable task-only pre-dispatch TTSR queue/store key. The later persisted
 * assistant entry does not yet exist; preAssistantAnchorEntryId is the exact
 * current leaf before that assistant message. captureGeneration is allocated
 * once for this canonical task call and never changes across streamed inputs.
 * Non-task tools never allocate this key or enter the durable settlement family.
 */
export interface ConfidentialTransientTaskForegroundPendingTtsrOverlayKeyV1 {
	readonly schemaVersion: 1;
	readonly parentSessionId: string;
	readonly parentSessionGenerationSha256: Sha256Ref;
	readonly preAssistantBranchGenerationSha256: Sha256Ref;
	readonly preAssistantAnchorEntryId: string | null;
	readonly toolCallId: string;
	readonly toolName: "task" | "eval";
	readonly captureGeneration: number;
	/** Stable across every tool/text/thinking input in this assistant stream. */
	readonly assistantStreamSha256: Sha256Ref;
	readonly keySha256: Sha256Ref;
}

