/** Closed route selected after the canonical Task invocation finishes or is abandoned. */
export type TransientTaskForegroundPostExecutionRouteCoreV1 =
	| {
			readonly route: "foreground_handoff_present";
			readonly classification: Extract<
				TransientTaskForegroundDispatchClassificationV1,
				{ core: { classification: "foreground_present" } }
			>;
			readonly executeEntryObservationReceipt: ConfidentialTransientTaskExecuteEntryObservationReceiptV1;
			readonly executeResultClassificationObservationReceipt: ConfidentialTransientTaskSourceObservationReceiptV1;
			/** Strictly positive. */
			readonly completedBlockingChildCount: number;
			readonly handoffBatchSha256: Sha256Ref;
	  }
	| {
			readonly route: "executed_without_handoff";
			readonly outcome: TransientTaskForegroundNoHandoffResultV1;
			readonly handoffBatchSha256?: never;
	  }
	| {
			readonly route: "post_hook_result_without_execution";
			readonly classification: null;
			readonly reason: "before_tool_block" | "before_tool_prepare_error";
			readonly priorSourceObservationReceipt: ConfidentialTransientTaskSourceObservationReceiptV1;
			readonly afterHookResultObservationReceipt: ConfidentialTransientTaskSourceObservationReceiptV1;
			readonly executeEntryObservationReceipt?: never;
			readonly handoffBatchSha256?: never;
	  }
	| {
			readonly route: "post_hook_result_without_execution";
			readonly classification: null;
			readonly reason: "argument_transform_error" | "pre_execute_error";
			readonly priorSourceObservationReceipt: null;
			readonly afterHookResultObservationReceipt: ConfidentialTransientTaskSourceObservationReceiptV1;
			readonly executeEntryObservationReceipt?: never;
			readonly handoffBatchSha256?: never;
	  }
	| {
			readonly route: "abandoned_without_after_hook";
			readonly classification: null;
			readonly reason:
				| "soft_requirement_detour"
				| "steering_skip"
				| "signal_pre_execution_skip"
				| "assistant_stream_terminal"
				| "tool_missing"
				| "initial_validation"
				| "hook_revision_validation";
			readonly sourceObservationReceipt: ConfidentialTransientTaskSourceObservationReceiptV1;
			readonly executeEntryObservationReceipt?: never;
			readonly handoffBatchSha256?: never;
	  };

