	readonly orderedAppendOperationIds: readonly [OperationId, ...OperationId[]];
	readonly orderedPreReturnIdentities: TransientTaskForegroundPreReturnIdentityEnvelopeListV1;
	readonly orderedPreReturnIdentitySha256s: readonly [Sha256Ref, ...Sha256Ref[]];
