export type TransientTaskMergeOnlyCaptureResultErrorV1 = `Merge failed: ${string}`;
export type TransientTaskMergePlusPatchCaptureResultErrorV1 =
	`Merge failed: ${string}; patch capture failed: ${string}`;
export type TransientTaskCaptureResultErrorV1 =
	| TransientTaskPatchOnlyCaptureResultErrorV1
	| TransientTaskMergeOnlyCaptureResultErrorV1
	| TransientTaskMergePlusPatchCaptureResultErrorV1;

