interface TransientTaskCaptureReceiptBaseV1 extends TransientTaskWorkspaceKeyV1 {
	readonly schemaVersion: 1;
	readonly capturePreparationId: OperationId;
	readonly captureId: OperationId;
	readonly preparationReceiptSha256: Sha256Ref;
	readonly preparedContentSha256: Sha256Ref;
	readonly effectIdentityManifest: TransientTaskEffectIdentityManifestV1;
	readonly planSha256: Sha256Ref;
	readonly captureRequestSha256: Sha256Hex;
	/** Exact expected-old ref state; physical cleanup is its sole consumer and deletion owner. */
	readonly captureRefState: ConfidentialTransientTaskCaptureRefStateV1;
	readonly captureRefStateSha256: Sha256Ref;
	/** Non-null exactly when the captured result includes the materialized root branch. */
	readonly captureMaterializationReceiptSha256: Sha256Ref | null;
	/** Empty exactly for branch `nested_only` and branch `no_changes`; every subeffect-opening outcome is non-empty and algorithm-ordered. */
	readonly orderedSubeffectReceiptSha256s: readonly [] | readonly [Sha256Ref, ...Sha256Ref[]];
	readonly fieldsSha256: Sha256Ref;
	readonly resultErrorSha256: Sha256Ref | null;
	readonly capturedAt: ISO8601;
	readonly receiptSha256: Sha256Ref;
}

/** Exact current capture outcomes, retained confidentially for deterministic composition. */
export type TransientTaskCaptureReceiptV1 = TransientTaskCaptureReceiptBaseV1 &
	(
		| {
				readonly outcome: "captured";
				readonly fields: Exclude<
					TransientTaskCapturedSingleResultFieldsV1,
					{ readonly kind: "none" | "branch_fallback_patch" }
				>;
				readonly resultError: null;
		  }
		| {
				readonly outcome: "no_changes";
				readonly fields: Extract<TransientTaskCapturedSingleResultFieldsV1, { readonly kind: "none" }>;
				readonly resultError: null;
		  }
		| {
				readonly outcome: "branch_fallback_patch";
				readonly fields: Extract<
					TransientTaskCapturedSingleResultFieldsV1,
					{ readonly kind: "branch_fallback_patch" }
				>;
				/** Exact merge-only form after the publication error is frozen and fallback patch capture succeeds. */
				readonly resultError: TransientTaskMergeOnlyCaptureResultErrorV1;
		  }
		| {
				readonly outcome: "patch_capture_failed";
				readonly failedStage: "patch_mode" | "branch_fallback";
				readonly fields: Extract<TransientTaskCapturedSingleResultFieldsV1, { readonly kind: "none" }>;
				readonly resultError:
					| TransientTaskPatchOnlyCaptureResultErrorV1
					| TransientTaskMergePlusPatchCaptureResultErrorV1;
		  }
	);

