interface TransientTaskCleanupPlanBaseV1 extends TransientTaskWorkspaceKeyV1 {
	readonly schemaVersion: 1;
	readonly cleanupId: OperationId;
	readonly cleanupAuthorityId: OperationId;
	readonly workspaceId: WorkspaceId;
	readonly expectedAuthorityRevision: number;
	readonly expectedCanonical: TransientTaskManagedWorkspaceRefV1;
	readonly expectedProvider: TransientTaskProviderWorkspaceIdentityV1;
	readonly pendingOutcomeSha256: Sha256Ref;
	readonly pendingOutcomeReceiptSha256: Sha256Ref;
	readonly acknowledgementAssessmentId: OperationId;
	readonly preservingDrain: Extract<RuntimeDrainPlan, { commitReplica: true; freezeAuthority: "live_fence" }>;
	readonly fastDiscardDrain: Extract<RuntimeDrainPlan, { commitReplica: false; freezeAuthority: "none" }>;
	/** Preallocated before cleanup; never replaced after the final checkpoint. */
	readonly replicaDeleteRequestId: ProviderRequestId;
	/** Task-domain tombstone identity, distinct from every other cleanup ID. */
	readonly replicaDeletionQuarantineId: OperationId;
	/** Frozen once in this plan; both are immediate task-cleanup instants. */
	readonly replicaDeletionPlannedAt: ISO8601;
	readonly replicaDeletionPurgeAfter: ISO8601;
	readonly canonicalDiscardId: OperationId;
	readonly terminalEvidenceId: OperationId;
	/** Exact isolation target copied from create/lifecycle authority for every outcome. */
	readonly publicationTargetId: OperationId;
	readonly publicationTargetKey: TransientTaskPublicationTargetKeyV1;
	readonly isolationCleanupId: OperationId;
	/** Byte-identical effectIdentityManifest.worktreePublicationId for every outcome. */
	readonly worktreePublicationId: OperationId;
	readonly effectIdentityManifestSha256: Sha256Ref;
	readonly resultPublicationId: OperationId;
	readonly resultPublicationTargetId: TransientTaskResultPublicationTargetId;
	readonly resultPublicationTargetCleanupId: OperationId;
	readonly pendingPayloadId: TransientTaskOutcomePayloadId;
	readonly pendingPayloadDeleteId: OperationId;
	readonly composedPayloadId: TransientTaskOutcomePayloadId;
	readonly composedPayloadDeleteId: OperationId;
	readonly plannedAt: ISO8601;
}

export type TransientTaskCleanupPlanV1 = TransientTaskCleanupPlanBaseV1 &
	(
		| {
				readonly outcome: "succeeded";
				readonly worktreePublicationUse: "publish";
		  }
		| {
				readonly outcome: "failed" | "cancelled";
				readonly worktreePublicationUse: "unused_non_success";
		  }
	);

export type TransientTaskCleanupBranchV1 =
	| {
			readonly kind: "preserve";
			readonly reason: "task_succeeded";
			readonly assessment: null;
	  }
	| {
			readonly kind: "preserve";
			readonly reason: "acknowledged_effects";
			readonly assessment: Extract<TransientTaskEffectsAssessmentV1, { status: "acknowledged" }>;
	  }
	| {
			readonly kind: "preserve";
			readonly reason: "uncertain_effects";
			readonly assessment: Extract<TransientTaskEffectsAssessmentV1, { status: "ambiguous" }>;
	  }
	| {
			readonly kind: "fast_discard";
			readonly reason: "no_acknowledged_effects";
			readonly assessment: Extract<TransientTaskEffectsAssessmentV1, { status: "none_acknowledged" }>;
	  };

