export type TransientTaskCleanupProgressV1 =
	| { readonly state: "planned" }
	| { readonly state: "admission_closed" }
	| { readonly state: "assessment_outcome_unknown" }
	| {
			readonly state: "branch_selected";
			readonly branch: TransientTaskCleanupBranchV1;
	  }
	| {
			readonly state: "runtime_draining";
			readonly branch: TransientTaskCleanupBranchV1;
			readonly runtime: Extract<RuntimeAttachment, { state: "draining" }>;
	  }
	| {
			readonly state: "worktree_publication_outcome_unknown";
			readonly branch: Extract<TransientTaskCleanupBranchV1, { reason: "task_succeeded" }>;
			readonly attempt: TransientTaskCanonicalWorktreePublicationAttemptV1;
	  }
	| {
			readonly state: "worktree_publication_not_applied";
			readonly branch: Extract<TransientTaskCleanupBranchV1, { reason: "task_succeeded" }>;
			readonly attempt: TransientTaskCanonicalWorktreePublicationAttemptV1;
			readonly proof: TransientTaskCanonicalWorktreePublicationNotAppliedReceiptV1;
	  }
	| {
			readonly state: "worktree_published";
			readonly branch: Extract<TransientTaskCleanupBranchV1, { reason: "task_succeeded" }>;
			readonly receipt: TransientTaskWorktreePublicationReceiptV1;
	  }
	| {
			readonly state: "runtime_released";
			readonly branch: TransientTaskCleanupBranchV1;
			readonly runtime: Extract<RuntimeAttachment, { state: "none" }>;
			readonly release: RuntimeLeaseReleaseResult;
			readonly worktreePublicationId: OperationId;
			readonly worktreePublicationUse: "published" | "unused_non_success";
			readonly worktreePublication: TransientTaskWorktreePublicationReceiptV1 | null;
	  }
	| {
			readonly state: "replica_delete_prepared";
			readonly branch: TransientTaskCleanupBranchV1;
			readonly prepared: TransientTaskPreparedReplicaDeleteV1;
	  }
	| {
			readonly state: "replica_delete_outcome_unknown";
			readonly branch: TransientTaskCleanupBranchV1;
			readonly prepared: TransientTaskPreparedReplicaDeleteV1;
	  }
	| {
			readonly state: "replica_deleted";
			readonly branch: TransientTaskCleanupBranchV1;
			readonly prepared: TransientTaskPreparedReplicaDeleteV1;
			readonly result: Extract<RuntimeReplicaDeleteResult, { status: "deleted" | "already_deleted" | "absent" }>;
	  }
	| {
			readonly state: "canonical_discard_outcome_unknown";
			readonly branch: TransientTaskCleanupBranchV1;
			readonly prepared: TransientTaskPreparedReplicaDeleteV1;
			readonly result: Extract<RuntimeReplicaDeleteResult, { status: "deleted" | "already_deleted" | "absent" }>;
	  }
	| {
			readonly state: "blocked";
			readonly branch: TransientTaskCleanupBranchV1 | null;
			readonly block: RuntimeBlock;
	  }
	| {
			readonly state: "canonical_provider_terminal";
			readonly evidence: TransientTaskCanonicalProviderTerminalEvidenceV1;
	  };

