interface RuntimeCommandSnapshotBase {
	readonly commandId: CommandId;
	readonly requestSha256: Sha256Hex;
	readonly sync: RuntimeCommandSyncStatus;
	/** Bounded UTF-8 projected through RuntimeProviderPathMapper. */
	readonly output: string;
	readonly truncated: boolean;
	readonly exitCode: number | null;
	readonly signal: RuntimeCommandTerminalSignalV1 | null;
	readonly updatedAt: ISO8601;
}

export type RuntimeCommandSnapshot =
	| (RuntimeCommandSnapshotBase & {
			readonly status: "reserved";
			readonly execution: {
				readonly certainty: "not_started";
				readonly proof: "reservation_without_attempt" | "backend_absent";
			};
	  })
	| (RuntimeCommandSnapshotBase & {
			readonly status: "start_unknown";
			readonly execution: { readonly certainty: "unknown" };
	  })
	| (RuntimeCommandSnapshotBase & {
			readonly status: "running";
			readonly execution: { readonly certainty: "started" };
	  })
	| (RuntimeCommandSnapshotBase & {
			readonly status: "succeeded" | "failed" | "cancelled";
			readonly execution: { readonly certainty: "completed" };
	  });

export type RuntimeCommandInspectResult =
	| {
			readonly status: "absent";
			readonly commandId: CommandId;
			readonly execution: {
				readonly certainty: "not_started";
				readonly proof: "provider_reservation_absent";
			};
	  }
	| { readonly status: "present"; readonly snapshot: RuntimeCommandSnapshot };

export type RuntimeCommandStartReconcileResult =
	| {
			readonly status: "not_started";
			readonly snapshot: Extract<RuntimeCommandSnapshot, { status: "reserved" }>;
	  }
	| {
			readonly status: "unknown";
			readonly snapshot: Extract<RuntimeCommandSnapshot, { status: "start_unknown" }>;
	  }
	| {
			readonly status: "observed";
			readonly snapshot: Exclude<RuntimeCommandSnapshot, { status: "reserved" | "start_unknown" }>;
	  };

