export interface RuntimeRecoveryFreezePlan {
	readonly locator: RuntimeRecoveryFreezeLocator;
	readonly canonicalCommitId: OperationId;
	readonly requests: {
		/** Subrequest parent `runtime_transition`/`locator.recoveryFreezeId`, ordinal `4`, operation `recovery_freeze`. */
		readonly freeze: RuntimeProviderRequestIdentity;
		/**
		 * The same parent, ordinal `5`, operation `checkpoint_acknowledgement`.
		 * Only request ID and parent are knowable before checkpoint/commit output;
		 * the full request digest is frozen later in checkpoint publication.
		 */
		readonly checkpointAcknowledgement: RuntimeParentOperationProviderRequestPreallocationV1;
		/** The same parent, ordinal `6`, operation `release`. */
		readonly release: RuntimeParentOperationProviderRequestIdentity;
	};
}

