export type RuntimeRecoveryFreezeImpossibilityCode =
	| "replica_absent"
	| "replica_image_missing"
	| "replica_image_invalid"
	| "acknowledged_mutation_ledger_incomplete";

export interface RuntimeRecoveryFreezeImpossibilityProof {
	readonly locator: RuntimeRecoveryFreezeLocator;
	readonly code: RuntimeRecoveryFreezeImpossibilityCode;
	/** Digest of the provider's closed, durable proof tuple; never raw payload. */
	readonly proofSha256: Sha256Hex;
	readonly observedAt: ISO8601;
}

export interface RuntimeRecoveryFreezeFrozenResult {
	readonly reference: FrozenReplicaCheckpointRef;
	/** Digest of sorted successful provider mutation identities included in the image. */
	readonly acknowledgedMutationsSha256: Sha256Hex;
	readonly observedRenewalSequence: number;
	readonly commandAdmission: "closed";
	readonly activeCommands: 0;
	readonly pendingSyncs: 0;
	readonly priorFence: "recovery_revoked" | "already_revoked" | "expired";
}

export type RuntimeRecoveryFreezeResult =
	| (RuntimeRecoveryFreezeFrozenResult & {
			readonly status: "frozen" | "already_frozen";
	  })
	| {
			readonly status: "preservation_impossible" | "already_proved_impossible";
			readonly proof: RuntimeRecoveryFreezeImpossibilityProof;
	  };

export type RuntimeRecoveryFreezeInspectResult =
	| {
			readonly status: "absent";
			readonly locator: RuntimeRecoveryFreezeLocator;
	  }
	| {
			readonly status: "in_progress";
			readonly locator: RuntimeRecoveryFreezeLocator;
			readonly phase: "sealing_admission" | "reconciling_commands" | "freezing_checkpoint";
			readonly activeCommands: number;
			readonly pendingSyncs: number;
			readonly observedAt: ISO8601;
	  }
	| (RuntimeRecoveryFreezeFrozenResult & { readonly status: "frozen" })
	| {
			readonly status: "preservation_impossible";
			readonly proof: RuntimeRecoveryFreezeImpossibilityProof;
	  };

