export type RuntimeReplicaCacheEvictionMode = "explicit" | "workspace_retention";

export type RuntimeReplicaCacheEvictionDeferredReason =
	| "not_released"
	| "active_compute"
	| "compute_ambiguous"
	| "checkpoint_unacknowledged"
	| "command_or_sync_ambiguous";

export interface RuntimeReplicaCacheEvictionPlan extends RuntimeProviderRequestIdentity {
	readonly requestedByOperationId: OperationId;
	readonly replica: RuntimeReplicaRef;
	/** Together with delayMs, this is the exact caller-frozen retention input. */
	readonly mode: RuntimeReplicaCacheEvictionMode;
	readonly delayMs: number;
	/** Durable basis; retentionDeadline must equal plannedAt plus delayMs. */
	readonly plannedAt: ISO8601;
	/** Frozen before provider transport; the provider may not derive or shift it. */
	readonly retentionDeadline: ISO8601;
}

export interface RuntimeReplicaCacheEvictionRequest extends RuntimeReplicaCacheEvictionPlan {
	readonly signal?: AbortSignal;
}

export interface RuntimeReplicaCacheEvictionAcceptance {
	readonly requestId: ProviderRequestId;
	readonly requestSha256: Sha256Hex;
	readonly replica: RuntimeReplicaRef;
	readonly retentionDeadline: ISO8601;
	readonly acceptedAt: ISO8601;
}

export interface RuntimeReplicaCacheEvictionAcceptancePending {
	readonly requestId: ProviderRequestId;
	readonly requestSha256: Sha256Hex;
	readonly replica: RuntimeReplicaRef;
	readonly retentionDeadline: ISO8601;
	readonly observedAt: ISO8601;
}

export interface RuntimeReplicaCacheEvictionRejection {
	readonly requestId: ProviderRequestId;
	readonly requestSha256: Sha256Hex;
	readonly replica: RuntimeReplicaRef;
	readonly retentionDeadline: ISO8601;
	readonly code: "provider_request_rejected";
	readonly observedAt: ISO8601;
}

export interface RuntimeReplicaCacheEvictionDeadlineMismatch {
	readonly requestId: ProviderRequestId;
	readonly requestSha256: Sha256Hex;
	readonly replica: RuntimeReplicaRef;
	readonly plannedRetentionDeadline: ISO8601;
	readonly providerRetentionDeadline: ISO8601;
	readonly observedAt: ISO8601;
}

export interface RuntimeReplicaCacheEvictionCompletion {
	readonly acceptance: RuntimeReplicaCacheEvictionAcceptance;
	readonly outcome: "evicted" | "already_evicted" | "absent";
	readonly completedAt: ISO8601;
	readonly receiptSha256: Sha256Ref;
}

export type RuntimeReplicaCacheEvictionRequestResult =
	| {
			readonly status: "accepted" | "already_accepted";
			readonly acceptance: RuntimeReplicaCacheEvictionAcceptance;
	  }
	| {
			readonly status: "acceptance_pending";
			readonly pending: RuntimeReplicaCacheEvictionAcceptancePending;
	  }
	| {
			readonly status: "rejected";
			readonly rejection: RuntimeReplicaCacheEvictionRejection;
	  }
	| {
			readonly status: "deadline_mismatch";
			readonly mismatch: RuntimeReplicaCacheEvictionDeadlineMismatch;
	  }
	| {
			readonly status: "complete";
			readonly result: RuntimeReplicaCacheEvictionCompletion;
	  };

export type RuntimeReplicaCacheEvictionInspectResult =
	| {
			readonly status: "not_started";
			readonly requestId: ProviderRequestId;
			readonly requestSha256: Sha256Hex;
			readonly replica: RuntimeReplicaRef;
			readonly retentionDeadline: ISO8601;
			readonly observedAt: ISO8601;
	  }
	| {
			readonly status: "acceptance_pending";
			readonly pending: RuntimeReplicaCacheEvictionAcceptancePending;
	  }
	| {
			readonly status: "accepted";
			readonly acceptance: RuntimeReplicaCacheEvictionAcceptance;
	  }
	| {
			readonly status: "deferred";
			readonly acceptance: RuntimeReplicaCacheEvictionAcceptance;
			readonly reason: RuntimeReplicaCacheEvictionDeferredReason;
			readonly nextAttemptAt: ISO8601;
			readonly observedAt: ISO8601;
	  }
	| {
			readonly status: "rejected";
			readonly rejection: RuntimeReplicaCacheEvictionRejection;
	  }
	| {
			readonly status: "deadline_mismatch";
			readonly mismatch: RuntimeReplicaCacheEvictionDeadlineMismatch;
	  }
	| {
			readonly status: "complete";
			readonly result: RuntimeReplicaCacheEvictionCompletion;
	  };

/**
 * Cache-eviction result and inspection validators use exact closed shapes.
 * Every echoed requestSha256 is the same unprefixed Sha256Hex as the plan and
 * must compare byte-for-byte; no validator adds, strips, accepts, or infers a
 * sha256: prefix. Proof-artifact receiptSha256 values remain Sha256Ref.
 */

export type RuntimeReplicaDeletionAuthorizationV1 =
	| {
			readonly domain: "persistent";
			/** Full post-drain plan and exact canonical tombstone are the authority. */
			readonly deletion: WorkspaceDeletionPlanV1;
			readonly deletionPlanCoreSha256: Sha256Ref;
			readonly deletionPlanSha256: Sha256Ref;
			readonly tombstone: WorkspaceTombstone;
	  }
	| {
			readonly domain: "transient_task";
			readonly taskId: TransientTaskId;
			readonly runId: TransientTaskRunId;
			readonly workspaceId: WorkspaceId;
			readonly cleanupId: OperationId;
			readonly cleanupAuthorityId: OperationId;
			readonly cleanupPlanSha256: Sha256Ref;
			readonly finalCheckpoint: WorkspaceCheckpoint;
			readonly replicaDeleteRequestId: ProviderRequestId;
			readonly replicaDeletionQuarantineId: OperationId;
			readonly replicaDeletionPlannedAt: ISO8601;
			readonly replicaDeletionPurgeAfter: ISO8601;
	  };

export interface RuntimeReplicaDeleteRequest extends RuntimeProviderRequestIdentity {
	readonly replica: RuntimeReplicaRef;
	readonly authorization: RuntimeReplicaDeletionAuthorizationV1;
	readonly signal?: AbortSignal;
}

export type RuntimeReplicaDeleteResult = {
	readonly request: RuntimeProviderRequestIdentity;
	readonly replica: RuntimeReplicaRef;
	readonly authorization: RuntimeReplicaDeletionAuthorizationV1;
	readonly observedAt: ISO8601;
} & (
	| {
			readonly status: "deleted" | "already_deleted" | "absent";
			readonly retryAfter: null;
			readonly receiptSha256: Sha256Ref;
	  }
	| {
			readonly status: "cleanup_pending";
			readonly retryAfter: ISO8601 | null;
			readonly receiptSha256: null;
	  }
);

export type RuntimeReplicaDeleteInspectResult =
	| RuntimeReplicaDeleteResult
	| {
			readonly status: "not_started";
			readonly request: RuntimeProviderRequestIdentity;
			readonly replica: RuntimeReplicaRef;
			readonly authorization: RuntimeReplicaDeletionAuthorizationV1;
			readonly observedAt: ISO8601;
			readonly retryAfter: null;
			readonly receiptSha256: null;
	  };

/** Closed fixture proving core -> request hashes -> complete plan, in order. */
export interface WorkspaceDeletionPlanCanonicalGoldenVectorV1 {
	readonly schemaVersion: 1;
	readonly core: WorkspaceDeletionPlanCoreV1;
	readonly deletionPlanCoreSha256: Sha256Ref;
	readonly tombstone: WorkspaceTombstone;
	/** Same unique UTF-8 replica-key order as core.replicaRequests. */
	readonly requestVectors: readonly {
		readonly requestId: ProviderRequestId;
		readonly replica: RuntimeReplicaRef;
		readonly deletionAuthorityDomain: "persistent";
		readonly canonicalTupleUtf8: string;
		readonly expectedRequestSha256: Sha256Hex;
	}[];
	readonly deletion: WorkspaceDeletionPlanV1;
	readonly deletionPlanSha256: Sha256Ref;
}

export type RuntimeProviderDiscoveryFailureCodeV1 = "provider_reported_unavailable" | "discovery_failed";

export type RuntimeProviderReportedUnavailableCodeV1 = Exclude<
	SafeDiagnosticCodeV1,
	RuntimeProviderDiscoveryFailureCodeV1
>;

export type RuntimeProviderDiscoveryProbeResult =
	| {
			readonly status: "available";
			readonly candidates: readonly RuntimeCandidate[];
	  }
	| {
			readonly status: "unavailable";
			readonly code: RuntimeProviderReportedUnavailableCodeV1;
			readonly candidates: readonly [];
	  };

export interface RuntimeProvider {
	readonly id: ProviderId;
	/** Static, side-effect-free provider capability; sorted and duplicate-free. */
	readonly supportedLocations: readonly RuntimeLocation[];
	/** Side-effect-free discovery; it never starts compute or allocates a replica. */
	discoverCandidates(requirements: RuntimeRequirements): Promise<RuntimeProviderDiscoveryProbeResult>;
	acquire(request: RuntimeAcquireRequest): Promise<RuntimeAcquireResult>;
	/** Authenticated and side-effect-free; never accepts a raw fence. */
	inspectAcquire(request: RuntimeAcquireInspectRequest): Promise<RuntimeAcquireInspectResult>;
	renew(request: RuntimeLeaseRenewRequest): Promise<RuntimeLeaseRenewalReceipt>;
	/** Authenticated control-plane inspection; never accepts a raw fence. */
	inspectRenewal(plan: RuntimeLeaseRenewalPlan): Promise<RuntimeLeaseRenewInspectResult>;
	push(request: RuntimePushRequest): Promise<RuntimePushResult>;
	/** Authenticated and side-effect-free; never accepts a raw fence. */
	inspectPush(request: RuntimePushInspectRequest): Promise<RuntimePushInspectResult>;
	inspect(request: {
		readonly replica: RuntimeReplicaRef;
		readonly leaseId: RuntimeLeaseId;
		readonly fence: RuntimeFence | null;
	}): Promise<RuntimeInspectResult>;
	inspectCommand(request: RuntimeCommandLocator): Promise<RuntimeCommandInspectResult>;
	reconcileCommandStart(request: RuntimeCommandLocator): Promise<RuntimeCommandStartReconcileResult>;
	quiesce(request: RuntimeQuiesceRequest): Promise<RuntimeQuiesceResult>;
	/** Authenticated and side-effect-free; never accepts a raw fence. */
	inspectQuiesce(request: RuntimeQuiesceInspectRequest): Promise<RuntimeQuiesceInspectResult>;
	checkpoint(request: RuntimeCheckpointRequest): Promise<RuntimeCheckpointResult>;
	/** Authenticated control-plane preservation after the live fence is lost. */
	recoveryFreeze(request: RuntimeRecoveryFreezeRequest): Promise<RuntimeRecoveryFreezeResult>;
	inspectRecoveryFreeze(request: RuntimeRecoveryFreezeRequest): Promise<RuntimeRecoveryFreezeInspectResult>;
	inspectCheckpoint(request: RuntimeCheckpointInspectRequest): Promise<RuntimeFrozenCheckpointInspectResult>;
	fetchCheckpoint(request: {
		readonly reference: FrozenReplicaCheckpointRef;
		readonly signal?: AbortSignal;
	}): Promise<RuntimeCheckpointFetchResult>;
	acknowledgeCheckpoint(request: RuntimeCheckpointAcknowledgeRequest): Promise<RuntimeCheckpointAcknowledgeResult>;
	/** Authenticated and side-effect-free; reconciles only this acknowledgement. */
	inspectCheckpointAcknowledgement(
		request: RuntimeCheckpointAcknowledgeInspectRequest,
	): Promise<RuntimeCheckpointAcknowledgeInspectResult>;
	revoke(request: RuntimeRevokeRequest): Promise<RuntimeRevokeResult>;
	/** Authenticated and side-effect-free; never accepts a raw fence. */
	inspectRevoke(request: RuntimeRevokeInspectRequest): Promise<RuntimeRevokeInspectResult>;
	release(request: RuntimeLeaseReleaseRequest): Promise<RuntimeLeaseReleaseResult>;
	/** Authenticated and side-effect-free; reconciles a lost release response. */
	inspectRelease(request: RuntimeLeaseReleaseInspectRequest): Promise<RuntimeLeaseReleaseInspectResult>;
	/** Accepts the exact frozen deadline before release; it does not require release. */
	requestReplicaCacheEviction(
		request: RuntimeReplicaCacheEvictionRequest,
	): Promise<RuntimeReplicaCacheEvictionRequestResult>;
	/** Side-effect-free: reconciles only the exact cache-eviction plan. */
	inspectReplicaCacheEviction(
		plan: RuntimeReplicaCacheEvictionPlan,
	): Promise<RuntimeReplicaCacheEvictionInspectResult>;
	/** Canonical-tombstone authority; cache eviction never substitutes for this. */
	deleteReplica(request: RuntimeReplicaDeleteRequest): Promise<RuntimeReplicaDeleteResult>;
	/** Side-effect-free: never starts compute or recreates replica bytes. */
	inspectReplicaDeletion(request: RuntimeReplicaDeleteRequest): Promise<RuntimeReplicaDeleteInspectResult>;
}

export interface RuntimeProviderRegistry {
	register(provider: RuntimeProvider): void;
	get(providerId: ProviderId): RuntimeProvider;
	list(): readonly RuntimeProvider[];
}

export type RuntimeProviderDiscoveryUnavailableV1 =
	| {
			readonly status: "unavailable";
			readonly code: "provider_reported_unavailable";
			readonly details: {
				readonly reportedCode: RuntimeProviderReportedUnavailableCodeV1;
			};
	  }
	| {
			readonly status: "unavailable";
			readonly code: "discovery_failed";
			readonly details: {
				readonly failureKind: "provider_call_failed" | "invalid_result";
			};
	  };

export type RuntimeProviderDiscoveryAvailability =
	| { readonly status: "available" }
	| RuntimeProviderDiscoveryUnavailableV1
	| {
			readonly status: "not_queried";
			readonly reason: "not_registered" | "disabled";
	  };

export interface RuntimeProviderDiscoveryObservation {
	readonly providerId: ProviderId;
	readonly registered: boolean;
	readonly enabled: boolean;
	readonly availability: RuntimeProviderDiscoveryAvailability;
	readonly supportedLocations: readonly RuntimeLocation[];
	/** Present for every observation, including the empty list. */
	readonly candidates: readonly RuntimeCandidate[];
}

export type RuntimeSchedulerHardFilterCode =
	| "configured_provider_missing"
	| "configured_provider_disabled"
	| "configured_provider_unavailable"
	| "configured_provider_location_conflict"
	| "provider_disabled"
	| "provider_unavailable"
	| "provider_no_candidates"
	| "candidate_unavailable"
	| "placement_mismatch"
	| "provider_id_mismatch"
	| "workspace_format_mismatch"
	| "capability_missing"
	| "os_mismatch"
	| "arch_mismatch"
	| "cpu_insufficient"
	| "memory_insufficient"
	| "network_mismatch"
	| "ready_latency_exceeded";

export interface RuntimeSchedulerProviderObservation {
	readonly providerId: ProviderId;
	readonly registered: boolean;
	readonly enabled: boolean;
	readonly availability: RuntimeProviderDiscoveryAvailability;
	readonly supportedLocations: readonly RuntimeLocation[];
	readonly candidateCount: number;
	readonly hardFilterFailures: readonly RuntimeSchedulerHardFilterCode[];
}

export interface RuntimeSchedulerCandidateObservation {
	readonly providerId: ProviderId;
	readonly profileId: ProfileId;
	readonly location: RuntimeLocation;
	readonly hardFilterFailures: readonly RuntimeSchedulerHardFilterCode[];
	readonly retainedCurrent: boolean;
	readonly estimatedIncrementalCostMicrosPerHour: number;
	readonly estimatedReadyLatencyMs: number;
}

export interface RuntimeScheduleRequest {
	readonly requirements: RuntimeRequirements;
	readonly current: RuntimeCandidate | null;
	/** Exactly one normalized observation per registered or configured provider. */
	readonly providers: readonly RuntimeProviderDiscoveryObservation[];
}

export interface RuntimeSchedulerEvaluation {
	readonly providers: readonly RuntimeSchedulerProviderObservation[];
	readonly candidates: readonly RuntimeSchedulerCandidateObservation[];
}

export type RuntimeScheduleResult =
	| (RuntimeSchedulerEvaluation & {
			readonly status: "selected";
			readonly candidate: RuntimeCandidate;
			readonly retainedCurrent: boolean;
	  })
	| (RuntimeSchedulerEvaluation & {
			readonly status: "unsatisfied";
			readonly unmet: readonly RuntimeSchedulerHardFilterCode[];
	  });

export interface RuntimeScheduler {
	select(request: RuntimeScheduleRequest): RuntimeScheduleResult;
}

export type RuntimeTransitionReason =
	| "first_tool"
	| "capability_change"
	| "policy_change"
	| "idle_timeout"
	| "park"
	| "agent_release"
	| "workspace_delete"
	| "task_complete"
	| "task_failed"
	| "task_cancelled"
	| "crash_recovery"
	| "lease_expired";

export interface RuntimeLeasePlan {
	readonly replica: RuntimeReplicaRef;
	readonly leaseId: RuntimeLeaseId;
	readonly fenceId: RuntimeFenceId;
	readonly initialRenewalSequence: 0;
	readonly baseCheckpoint: WorkspaceCheckpoint;
	/** Persisted in the provider reservation before acquire effects. */
	readonly deletionAuthorityDomain: RuntimeReplicaDeletionAuthorizationV1["domain"];
	readonly leaseTtlMs: number;
}

export interface RuntimeAcquisitionPlan {
	readonly transitionId: OperationId;
	readonly target: RuntimeTarget;
	readonly lease: RuntimeLeasePlan;
	/** Persisted before acquire and retained in active state before dispatch opens. */
	readonly recovery: RuntimeRecoveryFreezePlan;
	readonly requests: {
		readonly acquire: RuntimeTransitionProviderRequestIdentity;
		readonly push: RuntimeTransitionProviderRequestIdentity;
		readonly rollbackRevoke: RuntimeTransitionProviderRequestIdentity;
		readonly rollbackRelease: RuntimeParentOperationProviderRequestIdentity;
	};
}

export type RuntimeAcquireProgress =
	| {
			readonly phase: "pre_provider";
			readonly lease: null;
			readonly materialized: null;
	  }
	| {
			readonly phase: "acquire_outcome_unknown";
			readonly lease: null;
			readonly materialized: null;
	  }
	| {
			readonly phase: "reserved";
			readonly lease: RuntimeLeaseRef;
			readonly materialized: null;
	  }
	| {
			readonly phase: "push_outcome_unknown";
			readonly lease: RuntimeLeaseRef;
			readonly materialized: null;
	  }
	| {
			readonly phase: "ready";
			readonly lease: RuntimeLeaseRef;
			readonly materialized: RuntimePushResult;
	  };

export type RuntimeRecoveryFreezeProgress =
	| { readonly state: "not_started" }
	| {
			/** Persisted immediately before authenticated recovery-freeze transport. */
			readonly state: "outcome_unknown";
			readonly locator: RuntimeRecoveryFreezeLocator;
	  }
	| {
			readonly state: "in_progress";
			readonly locator: RuntimeRecoveryFreezeLocator;
			readonly phase: "sealing_admission" | "reconciling_commands" | "freezing_checkpoint";
			readonly activeCommands: number;
			readonly pendingSyncs: number;
			readonly observedAt: ISO8601;
	  }
	| {
			readonly state: "frozen";
			readonly result: RuntimeRecoveryFreezeFrozenResult;
	  }
	| {
			readonly state: "preservation_impossible";
			readonly proof: RuntimeRecoveryFreezeImpossibilityProof;
	  };

export interface RuntimeDiscardRuntimeChangesAuthorization {
	readonly schemaVersion: 1;
	readonly discardId: OperationId;
	readonly expectedAttachmentRevision: number;
	readonly ownerEpoch: number;
	readonly impossibility: RuntimeRecoveryFreezeImpossibilityProof;
	readonly authorizedAt: ISO8601;
}

export type RuntimeDiscardRuntimeChangesResult = {
	readonly status: "discarded" | "already_discarded";
	readonly authorization: RuntimeDiscardRuntimeChangesAuthorization;
	readonly checkpoint: WorkspaceCheckpoint;
};

export type RuntimeDrainPlan =
	| {
			readonly transitionId: OperationId;
			readonly commitReplica: false;
			readonly freezeAuthority: "none";
			readonly checkpointId: null;
			readonly canonicalCommitId: null;
			readonly recovery: null;
			readonly cacheEvictionPlan: null;
			readonly requests: {
				readonly quiesce: RuntimeTransitionProviderRequestIdentity;
				readonly checkpoint: null;
				readonly revoke: RuntimeTransitionProviderRequestIdentity;
				readonly checkpointAcknowledgement: null;
				readonly release: RuntimeParentOperationProviderRequestIdentity;
			};
	  }
	| {
			readonly transitionId: OperationId;
			readonly commitReplica: true;
			readonly freezeAuthority: "live_fence";
			readonly checkpointId: FrozenCheckpointId;
			readonly canonicalCommitId: OperationId;
			readonly recovery: null;
			/** Required for Cloudflare automatic retention; null for providers without it. */
			readonly cacheEvictionPlan: RuntimeReplicaCacheEvictionPlan | null;
			readonly requests: {
				readonly quiesce: RuntimeTransitionProviderRequestIdentity;
				readonly checkpoint: RuntimeTransitionProviderRequestIdentity;
				readonly revoke: RuntimeTransitionProviderRequestIdentity;
				readonly checkpointAcknowledgement: RuntimeParentOperationProviderRequestPreallocationV1;
				readonly release: RuntimeParentOperationProviderRequestIdentity;
			};
	  }
	| {
			readonly transitionId: OperationId;
			readonly commitReplica: true;
			readonly freezeAuthority: "control_plane_recovery";
			readonly checkpointId: FrozenCheckpointId;
			readonly canonicalCommitId: OperationId;
			/** Exact plan copied from PersistedActiveRuntime; no identity is minted here. */
			readonly recovery: RuntimeRecoveryFreezePlan;
			/** Adopted from the exact catalog row or allocated once before first submission. */
			readonly cacheEvictionPlan: RuntimeReplicaCacheEvictionPlan | null;
			readonly requests: {
				readonly quiesce: null;
				readonly checkpoint: null;
				readonly revoke: null;
				readonly checkpointAcknowledgement: RuntimeParentOperationProviderRequestPreallocationV1;
				readonly release: RuntimeParentOperationProviderRequestIdentity;
			};
	  };

export type RuntimeCheckpointPublication =
	| { readonly state: "not_requested" }
	| {
			readonly state: "freeze_outcome_unknown";
			readonly locator: FrozenReplicaCheckpointLocator;
	  }
	| {
			readonly state: "frozen";
			readonly reference: FrozenReplicaCheckpointRef;
	  }
	| {
			readonly state: "committed";
			readonly reference: FrozenReplicaCheckpointRef;
			readonly canonicalCommit: CanonicalWorkspaceCommitReceipt;
			/**
			 * Full late-bound request, including the digest of the exact reference
			 * and canonical commit tuple, durable before acknowledgement transport.
			 */
			readonly acknowledgementRequest: RuntimeCheckpointAcknowledgeInspectRequest;
	  }
	| {
			readonly state: "acknowledged";
			readonly reference: FrozenReplicaCheckpointRef;
			readonly canonicalCommit: CanonicalWorkspaceCommitReceipt;
			readonly acknowledgementRequest: RuntimeCheckpointAcknowledgeInspectRequest;
			readonly acknowledgement: RuntimeCheckpointAcknowledgeResult;
	  };

export type RuntimeDrainCacheEvictionProgress =
	| { readonly state: "not_required" }
	| { readonly state: "planned" }
	| { readonly state: "submission_outcome_unknown" }
	| {
			readonly state: "inspection_pending";
			readonly pending: RuntimeReplicaCacheEvictionAcceptancePending;
	  }
	| {
			readonly state: "accepted";
			readonly acceptance: RuntimeReplicaCacheEvictionAcceptance;
	  }
	| {
			readonly state: "deferred";
			readonly acceptance: RuntimeReplicaCacheEvictionAcceptance;
			readonly reason: RuntimeReplicaCacheEvictionDeferredReason;
			/** Mutable provider retry schedule; never a replacement plan deadline. */
			readonly nextAttemptAt: ISO8601;
	  }
	| {
			readonly state: "rejected";
			readonly rejection: RuntimeReplicaCacheEvictionRejection;
	  }
	| {
			readonly state: "deadline_mismatch";
			readonly mismatch: RuntimeReplicaCacheEvictionDeadlineMismatch;
	  }
	| {
			readonly state: "complete";
			readonly result: RuntimeReplicaCacheEvictionCompletion;
	  };

export type RuntimeReconcileTarget =
	| {
			readonly kind: "provider_request";
			readonly providerId: ProviderId;
			readonly requestId: ProviderRequestId;
	  }
	| { readonly kind: "lease"; readonly lease: RuntimeLeasePlan }
	| {
			readonly kind: "lease_renewal";
			readonly plan: RuntimeLeaseRenewalPlan;
	  }
	| {
			readonly kind: "recovery_freeze";
			readonly plan: RuntimeRecoveryFreezePlan;
	  }
	| {
			readonly kind: "command_start";
			readonly command: RuntimeCommandLocator;
	  }
	| {
			readonly kind: "frozen_checkpoint";
			readonly checkpoint: FrozenReplicaCheckpointLocator;
	  }
	| {
			readonly kind: "replica_cache_eviction";
			readonly plan: RuntimeReplicaCacheEvictionPlan;
	  }
	| {
			readonly kind: "canonical_commit";
			readonly workspaceId: WorkspaceId;
			readonly commitId: OperationId;
	  };

interface RuntimeBlockBase {
	readonly stage:
		| "operation_lease"
		| "provider_acquire"
		| "push"
		| "lease_renewal"
		| "recovery_freeze"
		| "quiesce"
		| "command_ambiguity"
		| "checkpoint"
		| "canonical_commit"
		| "checkpoint_acknowledgement"
		| "cache_eviction_acceptance"
		| "revoke"
		| "release"
		| "replica_delete"
		| "inspect";
	readonly code: SafeDiagnosticCodeV1;
	readonly observedAt: ISO8601;
}

export type RuntimeBlock =
	| (RuntimeBlockBase & {
			readonly state: "retry_allowed";
			readonly certainty: "not_started";
			readonly next: {
				readonly kind: "retry_same_request";
				readonly requestId: ProviderRequestId | CommandId;
			};
	  })
	| (RuntimeBlockBase & {
			readonly state: "reconcile_required";
			readonly certainty: "unknown";
			readonly next: RuntimeReconcileTarget;
	  })
	| (RuntimeBlockBase & {
			readonly state: "finish_required";
			readonly certainty: "started" | "completed";
			readonly next: {
				readonly kind: "finish_same_transition";
				readonly transitionId: OperationId;
			};
	  })
	| (RuntimeBlockBase & {
			readonly state: "operator_required";
			readonly certainty: "unknown" | "started" | "completed";
			readonly next: { readonly kind: "operator" };
	  });

export interface RuntimeTarget {
	readonly candidate: RuntimeCandidate;
	readonly requirements: RuntimeRequirements;
}

export interface PersistedActiveRuntime {
	readonly target: RuntimeTarget;
	readonly lease: RuntimeLeaseRef;
	/** Exact fence-free preservation identities durable before dispatch opens. */
	readonly recovery: RuntimeRecoveryFreezePlan;
	readonly renewal: RuntimeLeaseRenewalState;
}

export type RuntimeAttachment =
	| {
			readonly state: "none";
			readonly transitionId: null;
			readonly active: null;
			readonly lastDiscardedRuntimeChanges: RuntimeDiscardRuntimeChangesAuthorization | null;
			readonly block: RuntimeBlock | null;
	  }
	| {
			readonly state: "acquiring";
			readonly transitionId: OperationId;
			readonly active: null;
			readonly plan: RuntimeAcquisitionPlan;
			readonly progress: RuntimeAcquireProgress;
			readonly lastDiscardedRuntimeChanges: RuntimeDiscardRuntimeChangesAuthorization | null;
			readonly block: RuntimeBlock | null;
	  }
	| {
			readonly state: "active";
			readonly transitionId: null;
			readonly active: PersistedActiveRuntime;
			readonly lastDiscardedRuntimeChanges: RuntimeDiscardRuntimeChangesAuthorization | null;
			readonly block: null;
	  }
	| {
			readonly state: "draining";
			readonly transitionId: OperationId;
			readonly active: PersistedActiveRuntime;
			readonly reason: RuntimeTransitionReason;
			readonly plan: RuntimeDrainPlan;
			readonly publication: RuntimeCheckpointPublication;
			readonly recoveryFreeze: RuntimeRecoveryFreezeProgress | null;
			readonly cacheEviction: RuntimeDrainCacheEvictionProgress;
			/** Non-null only after the explicit owner action is durable. */
			readonly discardAuthorization: RuntimeDiscardRuntimeChangesAuthorization | null;
			readonly lastDiscardedRuntimeChanges: RuntimeDiscardRuntimeChangesAuthorization | null;
			readonly block: RuntimeBlock | null;
	  };

export interface RuntimeAttachmentRecordV1 {
	readonly schemaVersion: 1;
	/** Immutable identity of the create effect that first published this record. */
	readonly createId: OperationId;
	readonly revision: number;
	readonly workspaceId: WorkspaceId;
	readonly attachment: RuntimeAttachment;
	readonly scheduler: RuntimeSchedulerStatusSnapshot;
	readonly lastCompletedTransition: RuntimeCompletedTransitionReceipt | null;
	readonly updatedAt: ISO8601;
}

export type RuntimeAttachmentInvalidCodeV1 =
	| "invalid_json"
	| "unsupported_schema"
	| "key_body_mismatch"
	| "record_invariant_violation";

export type RuntimeAttachmentCreateConflictCodeV1 =
	| "create_id_mismatch"
	| "initial_record_mismatch"
	| "record_advanced";

export type RuntimeAttachmentCreateResultV1 =
	| {
			readonly status: "complete";
			readonly disposition: "created" | "already_complete";
			readonly record: RuntimeAttachmentRecordV1;
	  }
	| {
			readonly status: "missing";
			readonly workspaceId: WorkspaceId;
			readonly createId: OperationId;
	  }
	| {
			readonly status: "invalid";
			readonly workspaceId: WorkspaceId;
			readonly createId: OperationId;
			readonly code: RuntimeAttachmentInvalidCodeV1;
	  }
	| {
			readonly status: "conflict";
			readonly workspaceId: WorkspaceId;
			readonly createId: OperationId;
			readonly code: RuntimeAttachmentCreateConflictCodeV1;
			readonly existingCreateId: OperationId | null;
	  }
	| { readonly status: "controller_lost" }
	| { readonly status: "deletion_latched"; readonly deleteId: OperationId };

export type RuntimeAttachmentCreateInspectResultV1 =
	| { readonly status: "complete"; readonly record: RuntimeAttachmentRecordV1 }
	| {
			readonly status: "missing";
			readonly workspaceId: WorkspaceId;
			readonly createId: OperationId;
	  }
	| {
			readonly status: "invalid";
			readonly workspaceId: WorkspaceId;
			readonly createId: OperationId;
			readonly code: RuntimeAttachmentInvalidCodeV1;
	  }
	| {
			readonly status: "conflict";
			readonly workspaceId: WorkspaceId;
			readonly createId: OperationId;
			readonly code: "create_id_mismatch";
			readonly existingCreateId: OperationId;
	  };

export type RuntimeAttachmentAbortCreateResultV1 =
	| {
			readonly status: "missing";
			readonly disposition: "aborted" | "already_missing";
			readonly workspaceId: WorkspaceId;
			readonly createId: OperationId;
	  }
	| {
			readonly status: "invalid";
			readonly workspaceId: WorkspaceId;
			readonly createId: OperationId;
			readonly code: RuntimeAttachmentInvalidCodeV1;
	  }
	| {
			readonly status: "conflict";
			readonly workspaceId: WorkspaceId;
			readonly createId: OperationId;
			readonly code: RuntimeAttachmentCreateConflictCodeV1;
			readonly existingCreateId: OperationId | null;
	  }
	| { readonly status: "controller_lost" }
	| { readonly status: "deletion_latched"; readonly deleteId: OperationId };

export type RuntimeAttachmentReadResultV1 =
	| { readonly status: "present"; readonly record: RuntimeAttachmentRecordV1 }
	| { readonly status: "missing"; readonly workspaceId: WorkspaceId }
	| {
			readonly status: "invalid";
			readonly workspaceId: WorkspaceId;
			readonly code: RuntimeAttachmentInvalidCodeV1;
	  };

export type RuntimeAttachmentReplaceResultV1 =
	| { readonly status: "replaced"; readonly record: RuntimeAttachmentRecordV1 }
	| { readonly status: "missing"; readonly workspaceId: WorkspaceId }
	| { readonly status: "revision_conflict"; readonly currentRevision: number }
	| {
			readonly status: "create_id_conflict";
			readonly currentCreateId: OperationId;
	  }
	| {
			readonly status: "invalid";
			readonly workspaceId: WorkspaceId;
			readonly code: RuntimeAttachmentInvalidCodeV1;
	  }
	| { readonly status: "controller_lost" }
	| { readonly status: "deletion_latched"; readonly deleteId: OperationId };

export interface RuntimeAttachmentStore {
	create(request: {
		readonly createId: OperationId;
		readonly initial: RuntimeAttachmentRecordV1;
		readonly controllerLease: WorkspaceControllerLeaseProof;
	}): Promise<RuntimeAttachmentCreateResultV1>;
	inspectCreate(request: {
		readonly workspaceId: WorkspaceId;
		readonly createId: OperationId;
	}): Promise<RuntimeAttachmentCreateInspectResultV1>;
	abortCreate(request: {
		readonly workspaceId: WorkspaceId;
		readonly createId: OperationId;
		readonly controllerLease: WorkspaceControllerLeaseProof;
	}): Promise<RuntimeAttachmentAbortCreateResultV1>;
	read(workspaceId: WorkspaceId): Promise<RuntimeAttachmentReadResultV1>;
	replace(request: {
		readonly expectedRevision: number;
		readonly next: RuntimeAttachmentRecordV1;
		readonly controllerLease: WorkspaceControllerLeaseProof;
	}): Promise<RuntimeAttachmentReplaceResultV1>;
}

export type RuntimeStatusSnapshot = {
	readonly workspaceGeneration: number;
	readonly scheduler: RuntimeSchedulerStatusSnapshot;
	readonly transition: RuntimeTransitionStatusSnapshot;
	readonly checkpoint: RuntimeCheckpointStatusSnapshot;
	readonly replicaCleanup: RuntimeReplicaCleanupStatusSnapshot;
	readonly latency: RuntimeLatencyStatusSnapshot;
	readonly cost: RuntimeCostStatusSnapshot;
	readonly observedAt: ISO8601;
} & (
	| {
			readonly state: "none";
			readonly block: RuntimeBlock | null;
			readonly providerId: null;
			readonly profileId: null;
			readonly leaseId: null;
			readonly compute: null;
			readonly activeOperationCount: 0;
	  }
	| {
			readonly state: "acquiring";
			readonly block: RuntimeBlock | null;
			readonly providerId: ProviderId;
			readonly profileId: ProfileId;
			readonly leaseId: RuntimeLeaseId | null;
			readonly compute: RuntimeComputeState | null;
			readonly activeOperationCount: 0;
	  }
	| {
			readonly state: "active";
			readonly block: null;
			readonly providerId: ProviderId;
			readonly profileId: ProfileId;
			readonly leaseId: RuntimeLeaseId;
			readonly compute: RuntimeComputeState;
			readonly activeOperationCount: KnownOrUnknownCount;
	  }
	| {
			readonly state: "draining";
			readonly block: RuntimeBlock | null;
			readonly providerId: ProviderId;
			readonly profileId: ProfileId;
			readonly leaseId: RuntimeLeaseId;
			readonly compute: RuntimeComputeState;
			readonly activeOperationCount: KnownOrUnknownCount;
	  }
);

export interface WorkspaceOperationLease {
	readonly operationLeaseId: WorkspaceOperationLeaseId;
	readonly binding: RuntimeBinding;
	end(): void;
}

